L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "조리개 너머로 보이는 깨끗한 바다, 필터로 느껴지는 소금기 머금은 바람……."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "レンズ越しに見えるきれいな海、フィルターで感じられる潮気を含んだ風……"
L5_1.m_Talk_ENG = "The blue sea viewed through the aperture, salty wind blowing through the filter..."
L5_1.m_Talk_TWN = "越過橫膈膜看到的清澈大海，藉由過濾器受到鹹鹹的海風……"
L5_1.m_Talk_THA = "ดูทะเลสีครามผ่านช่องรับส่งสัญญาณ สายลมทะเลพัดผ่านเข้ามาทางตัวกรอง..."
L5_1.m_Talk_VTN = "Ngắm biển xanh qua khe hở, nếm được vị mặn của gió đang thổi qua tấm lọc..."
L5_1.m_Talk_SCN = "透过光圈看到的清澈大海，通过滤镜感受到的咸咸的海风……"
L5_1.m_Talk_DEU = "Das blaue Meer, durch die Linse gesehen, salziger Wind weht durch den Filter ..."
L5_1.m_Talk_FRA = "La mer bleue s'étend à perte d'ouverture, le vent salé me chatouille les filtres..."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 3200307
