L6_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "궤도 사이에 알알이 끼는 모래알, 검게 도색된 보디를 뜨겁게 달구는 태양까지……."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "装甲に挟まる砂粒、黒く塗色されたボディーを熱く熱す太陽まで……"
L6_1.m_Talk_ENG = "Sand getting into the caterpillar, and the sun burning my black painted body..."
L6_1.m_Talk_TWN = "卡在軌道間的沙粒，還有把身體烤焦的烈日……"
L6_1.m_Talk_THA = "เม็ดทรายที่เข้าไปในช่องล้อ แสงแดดที่แผดเผาลำตัวที่ทาสีดำของผม..."
L6_1.m_Talk_VTN = "Cát lọt vào bánh răng, và mặt trời đang đốt cháy cơ thể sơn đen của tôi ..."
L6_1.m_Talk_SCN = "夹在轨道之间的一粒粒细沙，炙烤着我这涂黑的身体的太阳……"
L6_1.m_Talk_DEU = "Sand dringt in die Ritzen ein und die Sonne verbrennt meinen schwarz lackierten Körper ..."
L6_1.m_Talk_FRA = "Le sable fin me pénètre les circuits, et le soleil brûlant se reflète sur ma coque obsidienne..."
