L13_1.m_Crash = 15
L13_1.m_Talk_KOREA = "응? 왜 그런가, 베로니카 양. 안색이 좋지 않네만?"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "うむ？　どうしたのかね、ベロニカ。顔色がよくないな。"
L13_1.m_Talk_ENG = "Hm? What’s wrong? You don’t look so well."
L13_1.m_Talk_TWN = "嗯？怎麼啦？你的臉色不太好？"
L13_1.m_Talk_THA = "หืม? เป็นอะไรรึเปล่าครับ? ดูท่าไม่ค่อยดีเลย"
L13_1.m_Talk_VTN = "Hừm? Sao thế? Trông cô không ổn lắm."
L13_1.m_Talk_SCN = "嗯？你怎么了，贝罗尼卡。你脸色看起来不太好呢？"
L13_1.m_Talk_DEU = "Hm? Was ist los? Sie sehen unwohl aus."
L13_1.m_Talk_FRA = "Hé bien, qu'y a-t-il ? Tu n'as pas l'air dans ton assiette."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 3200307
