L14_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L14_1.m_Pos = "L"
L14_1.m_Talk_KOREA = "메이드로서……  전 그저 주인님께 송구할 따름입니다."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "メイドとして……私はただご主人様に申し訳ない気持ちでいっぱいです。"
L14_1.m_Talk_ENG = "As your maid... I am sorry, Master."
L14_1.m_Talk_TWN = "身為女僕……我對主人感到抱歉。"
L14_1.m_Talk_THA = "ในฐานะเมดของคุณ... ฉันขออภัยค่ะ นายท่าน"
L14_1.m_Talk_VTN = "Là hầu gái của ngài... Tôi xin lỗi, Chủ Nhân."
L14_1.m_Talk_SCN = "我只是作为女仆…觉得愧对主人而已。"
L14_1.m_Talk_DEU = "Als Ihr Hausmädchen ... tut es mir leid, Meister."
L14_1.m_Talk_FRA = "En tant que domestique... Je vous dois des excuses, Maître."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@15#Talk"
L15_1.m_CutScenProcessKey = 15
