L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "どういうことかね？"
L15_1.m_Talk_ENG = "Why?"
L15_1.m_Talk_TWN = "那又是什麼意思?"
L15_1.m_Talk_THA = "ทำไมล่ะ?"
L15_1.m_Talk_VTN = "Sao thế?"
L15_1.m_Talk_SCN = "你那又是什么意思？"
L15_1.m_Talk_DEU = "Wieso denn?"
L15_1.m_Talk_FRA = "Des excuses ? Pourquoi donc ?"
L16_1 = {}
L16_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 3200307
L16_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L16_1.m_Pos = "L"
L16_1.m_Talk_KOREA = "주인님께서 안락한 휴가를 보내지 못한 건 메이드장인 제 책임이 가장 크기 때문입니다."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "ご主人様が穏やかなバカンスを過ごせなかったのは、メイド長である私の責任が最も大きいためです。"
L16_1.m_Talk_ENG = "I’m the one who is responsible for you not having a nice and relaxing vacation."
L16_1.m_Talk_TWN = "主人沒能悠閒地度過假期，身為女僕長的我要負最大的責任。"
L16_1.m_Talk_THA = "ฉันคือคนที่ต้องรับผิดชอบการที่คุณไม่ได้พักร้อนอย่างผ่อนคลาย"
L16_1.m_Talk_VTN = "Tôi là người chịu trách nhiệm về việc ngài không được nghỉ ngơi vui vẻ và thư giãn."
L16_1.m_Talk_SCN = "因为没能让主人愉快地休假，身为女仆长的我应当承担最大的责任。"
L16_1.m_Talk_DEU = "Ich bin diejenige, die Verantwortung dafür trägt, dass Sie keinen schönen und erholsamen Urlaub haben, Sir."
L16_1.m_Talk_FRA = "C'est de ma faute, si vous n'avez pas pu vous relaxer en premier lieu."
