L18_1.m_Talk_DEU = "Haha, wer sagt das denn?"
L18_1.m_Talk_FRA = "Ha ha ha, mais qui t'a dit des choses pareilles ?"
L19_1 = {}
L19_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 3200307
L19_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_IDLE"
L19_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L19_1.m_Pos = "C"
L19_1.m_Talk_KOREA = "내가 아는 한, 누구도 그렇게 생각하지 않을 걸세."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "私の知る限り、誰もそう思っていないはずさ。"
L19_1.m_Talk_ENG = "As far as I know, no one will blame you for this."
L19_1.m_Talk_TWN = "完全不會有人這麼想吧？"
L19_1.m_Talk_THA = "เท่าที่ผมรู้ ไม่มีใครโทษคุณเรื่องนี้นะ"
L19_1.m_Talk_VTN = "Theo như tôi biết, sẽ chả ai trách cô về chuyện này đâu."
L19_1.m_Talk_SCN = "据我所知，谁都不会那么想。"
L19_1.m_Talk_DEU = "Soweit ich weiß, wird Ihnen das niemand vorwerfen."
L19_1.m_Talk_FRA = "Autant que je sache, personne ne vous en veut pour ça."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 3200307
L20_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
