L20_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L20_1.m_Pos = "C"
L20_1.m_Talk_KOREA = "아니요. 이건 제 스스로의 마음가짐 문제입니다."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "いいえ。これは自分自身の心構えの問題です。"
L20_1.m_Talk_ENG = "No, it’s a matter of principle."
L20_1.m_Talk_TWN = "不，這是我自己心態的問題。"
L20_1.m_Talk_THA = "ไม่ค่ะ มันเป็นเรื่องของหลักการ"
L20_1.m_Talk_VTN = "Không, đó là vấn đề về khuôn phép."
L20_1.m_Talk_SCN = "不是的。这是我自己的心态问题。"
L20_1.m_Talk_DEU = "Nein, es geht ums Prinzip."
L20_1.m_Talk_FRA = "Peut-être, mais c'est une question de principes."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 3200307
L21_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_IDLE"
L21_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "자리를 지키도록 허락해 주신 이상, 지금부터라도 최선을 다해 주인님 곁을 보필하겠습니다."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "お供することを許していただいた以上、今からでも最善を尽くしてご主人様をそばでお守りします。"
L21_1.m_Talk_ENG = "Since you let me stay by your side, I want to serve you as best as I can."
L21_1.m_Talk_TWN = "既然允許我堅守崗位，那從現在開始我會盡全力輔佐主人。"
L21_1.m_Talk_THA = "ในเมื่อคุณยอมให้ฉันอยู่ข้างๆ คุณ ฉันก็อยากจะรับใช้คุณอย่างสุดความสามารถค่ะ"
L21_1.m_Talk_VTN = "Vì ngài đã cho tôi ở bên cạnh, tôi muốn phục vụ ngài tốt nhất có thể."
L21_1.m_Talk_SCN = "既然您允许我守护您了，那么从现在开始，我会尽自己最大的努力辅佐主人。"
L21_1.m_Talk_DEU = "Da Sie mich an Ihrer Seite bleiben lassen, möchte ich Ihnen so gut wie möglich dienen."
L21_1.m_Talk_FRA = "Puisque vous me laissez rester à vos côtés, je veux vous servir du mieux que je peux."
