L24_1 = {}
L24_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@24#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 3200307
L24_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_LAUGH"
L24_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L24_1.m_Pos = "R"
L24_1.m_Talk_KOREA = "하하. 그럴 필요 없네."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "ハハハ、その必要はない。"
L24_1.m_Talk_ENG = "Hah hah. That won’t be necessary."
L24_1.m_Talk_TWN = "哈哈，不用啦。"
L24_1.m_Talk_THA = "ฮ่าๆ ไม่จำเป็นหรอก"
L24_1.m_Talk_VTN = "Ha ha. Việc đó không cần thiết đâu."
L24_1.m_Talk_SCN = "哈哈，用不着这样。"
L24_1.m_Talk_DEU = "Hahaha. Das wird nicht nötig sein."
L24_1.m_Talk_FRA = "Ha ha. Ce ne sera pas nécessaire."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 3200307
L25_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L25_1.m_Pos = "R"
L25_1.m_Crash = 20
L25_1.m_Talk_KOREA = "모처럼의 휴가이지 않은가. 그러니 베로니카 양도 자신만의 추억을 쌓는 건 어떤가?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "せっかくの休みじゃないか。だからベロニカもここで思い出を作るのはどうかね？"
L25_1.m_Talk_ENG = "It’s a vacation. Why don’t you go and have fun yourself?"
L25_1.m_Talk_TWN = "這麼難得休假，你也留下屬於自己的回憶吧？"
L25_1.m_Talk_THA = "นี่เป็นพักร้อนนะ ทำไมคุณไม่ไปสนุกบ้างล่ะ?"
L25_1.m_Talk_VTN = "Đang nghỉ mà. Sao cô không đi chơi đi?"
L25_1.m_Talk_SCN = "难得休假不是吗？所以贝罗尼卡你也留下属于自己的回忆怎么样？"
L25_1.m_Talk_DEU = "Es ist ein Urlaub. Warum gehen Sie nicht und haben selbst Spaß?"
L25_1.m_Talk_FRA = "Nous sommes en vacances, après tout ! Pourquoi n'irais-tu pas prendre un peu de bon temps ?"
L26_1 = {}
L26_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 3200307
L26_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_IDLE"
L26_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L26_1.m_Pos = "L"
L26_1.m_Crash = 10
L26_1.m_Talk_KOREA = "걱정해 주시는 마음은 알겠지만, 전 그럴 수 없습니다."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "心配してくださる気持ちはわかりますが、私はそうすることができません。"
L26_1.m_Talk_ENG = "I understand your concern, but I can’t do that."
L26_1.m_Talk_TWN = "我明白主人的好意，但我不能那樣。"
L26_1.m_Talk_THA = "ฉันเข้าใจที่คุณเป็นห่วงนะคะ แต่ฉันทำแบบนั้นไม่ได้"
L26_1.m_Talk_VTN = "Tôi hiểu sự quan tâm của ngài, nhưng tôi không thể làm vậy."
L26_1.m_Talk_SCN = "我知道您很担心我，但是我不能那样做。"
L26_1.m_Talk_DEU = "Ich verstehe Ihre Bedenken, aber das kann ich nicht."
L26_1.m_Talk_FRA = "Je comprends votre inquiétude, mais je ne peux pas accepter."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 3200307
L27_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L27_1.m_Pos = "L"
L27_1.m_Talk_KOREA = "혹시 모를 위험을 대비하여 최소한의 경호인력은 필요합니다."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "万が一の危険に備えて、最低限の警護人員は必要です。"
L27_1.m_Talk_ENG = "Someone has to keep you safe just in case."
L27_1.m_Talk_TWN = "必須維持最基本的人力保護主人的安全。"
L27_1.m_Talk_THA = "ต้องมีคนคอยดูแลให้คุณปลอดภัย"
L27_1.m_Talk_VTN = "Phải có người giữ an toàn cho ngài, lỡ như có chuyện xảy ra."
L27_1.m_Talk_SCN = "为应对未知危险，需要最低限度的警卫人员。"
L27_1.m_Talk_DEU = "Jemand muss Sie für alle Fälle beschützen."
L27_1.m_Talk_FRA = "Le danger peut survenir à tout moment, quelqu'un doit vous protéger."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "SUMMER2021_ACT3_STAGE4_START@28#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 3200307
L28_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_DESPAIR"
L28_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L28_1.m_Pos = "R"
L28_1.m_Talk_KOREA = "아무리 그래도 좀 쉬어야지."
L28_1.m_fTalkTime = 0.03
L29_1 = "いくら君でも休みは必要だ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Still, you need some rest."
L28_1.m_Talk_ENG = L29_1
L29_1 = "再怎麼說也得休息一下吧。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แต่คุณก็ยังต้องพักบ้างนะครับ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Dù vậy thì cô cũng cần nghỉ ngơi."
L28_1.m_Talk_VTN = L29_1
L29_1 = "不管怎么样，你也得休息啊。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Trotzdem brauchen Sie etwas Auszeit."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Certes, mais tu dois quand même te reposer."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "SUMMER2021_ACT3_STAGE4_START@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3200307
L29_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L29_1.m_Pos = "R"
L30_1 = "자네가 그렇게 잠도 줄여가며 일하다가 골병이라도 들면, 내 마음도 편치 않을 거야."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "君がそうして睡眠時間を削って仕事をして体調でも崩したら、私の気持ちも穏やかではなくなるぞ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "If you exert yourself and get sick, I’m going to blame myself for that."
L29_1.m_Talk_ENG = L30_1
L30_1 = "你這樣不睡覺工作，萬一生病，我心裡也不會好過的。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "หากคุณใช้แรงเกินตัวแล้วป่วยขึ้นมา ผมต้องโทษตัวเองแน่ๆ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nếu cô cố quá rồi ngã bệnh, tôi sẽ tự trách mình vì chuyện đó."
L29_1.m_Talk_VTN = L30_1
L30_1 = "你那样废寝忘食地工作，万一病倒了，我的心里也会不安的。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Wenn Sie sich anstrengen und krank werden, bin ich dafür verantwortlich."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Si tu tombais malade à force de surmenage, je n'aurais pas la conscience tranquille."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "SUMMER2021_ACT3_STAGE4_START@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3200307
L30_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "UNIT_PRIDE"
L30_1.m_Face = L31_1
L30_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L30_1.m_Pos = "L"
L31_1 = "염려 마시길. 저에겐 주인님 곁을 지키는 것이 가장 편안한 휴식입니다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ご心配に及びません。私にはご主人様をそばでお守りすることが最も安らかな休憩です。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Don’t worry about it, Master. Staying by your side is the most relaxing time for me."
L30_1.m_Talk_ENG = L31_1
L31_1 = "請不要擔心。對我來說，守在主人身邊就是最棒的休息。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ไม่ต้องห่วงค่ะ นายท่าน การได้อยู่ข้างๆ คุณคือช่วงเวลาที่ผ่อนคลายที่สุดสำหรับฉันค่ะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đừng lo về chuyện đó, Chủ Nhân. Ở bên cạnh ngài là khoảng thời gian thư giãn nhất của tôi."
L30_1.m_Talk_VTN = L31_1
L31_1 = "您别担心。对我来说，守在主人左右就是最好的休息。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Machen Sie sich keine Sorgen, Sir. Der Aufenthalt an Ihrer Seite ist für mich die erholsamste Zeit."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Ne vous inquiétez pas, Maître. Rester à vos côtés, il n'y a rien de plus relaxant pour moi."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3200307
L31_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L31_1.m_bWaitClick = false
L31_1.m_fWaitTime = 0
L31_1.m_bClear = true
L32_1 = {}
L33_1 = "SUMMER2021_ACT3_STAGE4_START@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3200307
L32_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_PRIDE"
L32_1.m_Face = L33_1
L32_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "흐음…. 그렇게까지 말한다면 어쩔 수 없지."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ふむ……そこまで言うなら仕方ないな。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Hm... Okay, if you say so."
L32_1.m_Talk_ENG = L33_1
L33_1 = "這樣喔……那就照你的意思吧。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "อืม... โอเค ถ้าคุณว่าอย่างนั้น"
L32_1.m_Talk_THA = L33_1
L33_1 = "Hừm... Được rồi, nếu cô đã nói vậy."
L32_1.m_Talk_VTN = L33_1
L33_1 = "嗯……既然你都这么说了，那就没办法了。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Hm ... Okay, wenn Sie meinen."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Hmm... Très bien, si tu le dis."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SUMMER2021_ACT3_STAGE4_START@33#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 33
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3200307
L33_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "그럼 내가 자네를 위한 <color=#ffd34c>추가 업무</color>를 찾아보겠네."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "それじゃあ私が君のために<color=#ffd34c>追加業務</color>を探してみるとしよう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I’ll try to find an <color=#ffd34c>additional task</color> for you."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我替你找點<color=#ffd34c>額外的工作</color>！。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ผมจะพยายามหา<color=#ffd34c>งานเสริม</color>ให้นะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi sẽ cố tìm một <color=#ffd34c>nhiệm vụ bổ sung</color> cho cô."
L33_1.m_Talk_VTN = L34_1
L34_1 = "那我得再给你找点<color=#ffd34c>额外工作</color>才行。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich werde versuchen, eine <color=#ffd34c>zusätzliche Aufgabe</color> für Sie zu finden."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Dans ce cas, je vais essayer de te trouver une <color=#ffd34c>mission supplémentaire</color> à accomplir."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "SUMMER2021_ACT3_STAGE4_START@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3200307
L34_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_Face = "UNIT_DESPAIR"
L34_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "아주 피곤하고, 특별한 의미도 없고, 심지어 별도의 수당도 없는 성가신 업무일지도 모르지."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "とても疲れるし、特別な意味もない。しかも別途の手当てもない煩わしい業務かもしれない。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "It could be something very tiresome, meaningless, and without payment."
L34_1.m_Talk_ENG = L35_1
L35_1 = "很累人，又有點沒意義，甚至沒有額外補助的麻煩事。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "อาจจะเป็นงานที่เหนื่อยมาก ไร้ความหมาย และไร้ค่าตอบแทน"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nó có thể là một cái gì đó rất mệt mỏi, vô nghĩa và không được trả tiền."
L34_1.m_Talk_VTN = L35_1
