L37_1 = "네. 주인님을 위해서라면 어떤 궂은 일이든 수행할 준비가 되어 있으니까요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "はい。ご主人様のためなら、どんな厳しい仕事でも遂行する準備ができていますから。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Of course. I’m always ready to serve you."
L36_1.m_Talk_ENG = L37_1
L37_1 = "是的。只要主人開口，無論是什麼麻煩事，我都可以執行。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แน่นอนค่ะ ฉันพร้อมรับใช้คุณเสมอ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tất nhiên rồi. Tôi luôn luôn sẵn sàng phục vụ ngài."
L36_1.m_Talk_VTN = L37_1
L37_1 = "没关系。只要是为了主人，不管多棘手的工作，我都做好了欣然执行的准备。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ja. Ich bin immer bereit, Ihnen zu dienen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Bien sûr. Je suis toujours prête à vous servir."
L36_1.m_Talk_FRA = L37_1
