L4_1 = "헤헤, 펭귄들이랑 노느라 종이 비행기로 만들어 버렸어~ 미안~"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "へへ、ペンギンたちと遊ぶ時、紙飛行機にしちゃった～！　ごめんね～！"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Heh heh. I used it to make paper planes when I was playing with the penguins. Sorry!"
L3_1.m_Talk_ENG = L4_1
L4_1 = "嘿嘿，我折成紙飛機和企鵝一起玩了～對不起～"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แหะๆ ฉันเอาไปใช้พับเครื่องบินกระดาษตอนที่เล่นกับพวกเพนกวินน่ะ โทษที!"
L3_1.m_Talk_THA = L4_1
L4_1 = "Hì hì. Tôi dùng nó để gấp máy bay giấy khi chơi với lũ cánh cụt rồi. Xin lỗi nhé!"
L3_1.m_Talk_VTN = L4_1
