L3_1.m_Talk_SCN = L4_1
L4_1 = "Hehehe. Ich habe daraus Papierflieger gefaltet, als ich mit den Pinguinen gespielt habe. Sorry!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Hé hé. J'en ai fait des avions en papier tout à l'heure, en jouant avec les pingouins. Sorry !"
