L10_1.m_Crash = 25
L11_1 = "히힛~ 제나처럼 고지식하게 여행하면 재미없어~"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "へへっ！　ジーナみたいに計画して旅行をしたら面白くないよ？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Heh heh, a planned tour is no fun, Zena!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "嘻嘻～像珍娜那樣照既定行程走有什麼好玩的～"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แหะๆ ทัวร์แบบวางแผนไว้ก่อนมันไม่สนุกหรอกน่า เซน่า!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Hì hì, một chuyến đi được vạch trước thì thường không vui, Zena à!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "嘻嘻~像珍娜那样死板地旅游没意思~"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Heh heh, eine geplante Tour macht keinen Spaß, Zena!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Hi hi. Arrête un peu de suivre ton guide, Zena !"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "SUMMER2021_ACT3_STAGE4_START@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3200307
L11_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
