L12_1 = "IRIE_CIVIL_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "원래 여행은 즉흥적으로 그때그때 결정해야 재밌는 거라구~♪"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "本来旅行は、即興でその都度決めて進んだほうが面白いもーん♪"
L11_1.m_Talk_JPN = L12_1
L12_1 = "It’s much more fun to go with the flow! ♪"
L11_1.m_Talk_ENG = L12_1
L12_1 = "旅行就要隨興，走一步算一步才好玩嘛～♪"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ปล่อยให้เป็นไปตามธรรมชาติน่ะสนุกกว่าเยอะ! ♪"
L11_1.m_Talk_THA = L12_1
L12_1 = "Đi theo ngẫu hứng thì vui hơn nhiều! ♪"
L11_1.m_Talk_VTN = L12_1
L12_1 = "旅游本来就是随性地决定才有意思~♪"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Es macht viel mehr Spaß, mit dem Lauf der Dinge zu gehen! ♪"
L11_1.m_Talk_DEU = L12_1
L12_1 = "C'est bien plus amusant de se laisser porter par le courant ! ♪"
L11_1.m_Talk_FRA = L12_1
