L22_1 = "어? 그런데 제나는 왜 옷 안 갈아 입어?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "あれ？　てかジーナはなんで着替えないの？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Huh? Why aren’t you changing, Zena?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "嗯？不過珍你什麼不換衣服？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "หืม? ทำไมไม่เปลี่ยนเสื้อผ้าล่ะ เซน่า?"
