L22_1 = "Hử? Sao cậu không thay đồ hả, Zena?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "咦？不过珍娜你怎么不换衣服？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Hä? Warum ziehst du dich nicht um, Zena?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Hein ? Au fait, pourquoi tu te changes pas, toi ?"
L21_1.m_Talk_FRA = L22_1
