L22_1.m_Pos = "L"
L23_1 = "아하, 제나도 맞는 옷이 없었구나?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "あ、ジーナもサイズが合う服がなかったんだね！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Oh, you couldn’t find the right dress for you, right?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "哈哈，你也沒有合適的衣服嗎？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "อ๋อ เธอเลือกเดรสที่ใช่ไม่ได้ใช่มั้ย?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Ồ, cậu không thể tìm thấy chiếc váy cho tôi, phải không?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "啊哈，珍娜也没有合适的衣服啊？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Oh, du konntest nicht das richtige Kleid für dich finden, oder?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ah... Toi non plus, tu n'as pas trouvé de robe à ta taille ?"
L22_1.m_Talk_FRA = L23_1
