L25_1 = "SUMMER2021_ACT3_STAGE4_START@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3200307
L24_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_DESPAIR"
L25_1 = "ZENA_CIVIL_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "R"
L24_1.m_Crash = 15
L25_1 = "그, 그냥 그런 옷을 입고 사진 찍는 건…… 좀 더 나중에 친한 사람들을 잔뜩 초대해서 공식적으로……."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "そ、そんな服を着て写真を撮るのは……後で親しい人だけ招待して正式に……"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I-it’s just that... If I have to wear a wedding dress, I’d rather wear it in a proper ceremony... with my friends invited..."
L24_1.m_Talk_ENG = L25_1
L25_1 = "只是…穿婚紗拍照……應該要等到以後邀請親朋好友一起見證……"
L24_1.m_Talk_TWN = L25_1
L25_1 = "กะ-ก็แค่ว่า... ถ้าฉันต้องสวมชุดแต่งงาน ฉันอยากสวมในพิธีจริงมากกว่า... โดยที่เชิญเพื่อนๆ ของฉันมาด้วย..."
L24_1.m_Talk_THA = L25_1
L25_1 = "C-chỉ là... Nếu phải mặc váy cưới, tôi muốn mặc nó ở một buỗi lễ hẳn hoi... mời bạn bè đến dự nữa..."
L24_1.m_Talk_VTN = L25_1
L25_1 = "我、我就是觉得穿着那种衣服拍照……得邀请一大堆亲朋好友，正式地……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "E-es ist nur so ... Wenn ich ein Hochzeitskleid tragen muss, trage ich es lieber bei einer richtigen Zeremonie ... mit meinen eingeladenen Freunden ..."
L24_1.m_Talk_DEU = L25_1
L25_1 = "C'est juste que... Si je dois porter une robe de mariée, je préfère que ce soit lors d'une véritable cérémonie... avec ma famille et des amis que j'aurais invités..."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
