L26_1 = "헤헷, 부끄럼쟁이라서 그렇구나?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "へへっ、恥ずかしがり屋さんなんだね？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Heh heh, so you’re shy!"
L25_1.m_Talk_ENG = L26_1
L26_1 = "嘿嘿，害羞就直說嘛！"
L25_1.m_Talk_TWN = L26_1
L26_1 = "แหะๆ ที่แท้ก็อายนี่เอง!"
L25_1.m_Talk_THA = L26_1
L26_1 = "He he, thế là cậu xấu hổ!"
L25_1.m_Talk_VTN = L26_1
L26_1 = "嘿嘿，原来你是害羞啊？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Heh heh, also bist du schüchtern!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Hi hi. Tu es timide, c'est ça ?"
L25_1.m_Talk_FRA = L26_1
