L27_1 = 30
L26_1.m_Crash = L27_1
L27_1 = "아깝다~ 제나가 부끄러워하는 모습을 볼 수 있는 찬스였는데~♪"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "残念！　ジーナが恥ずかしがる姿が見れるチャンスだったのに～♪"
L26_1.m_Talk_JPN = L27_1
L27_1 = "It’s a shame! I would have loved to see you blushing, Zena!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "真可惜～原本可以看到珍娜害羞的樣子的～♪"
L26_1.m_Talk_TWN = L27_1
L27_1 = "น่าเสียดายนะ! ฉันอยากเห็นเธอหน้าแดงนะ เซน่า!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Thật đáng tiếc! Tôi sẽ rất vui khi thấy cậu đỏ mặt, Zena!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "真可惜~这可是看到珍娜害羞的样子的好机会呢~♪"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Schade! Ich hätte dich gerne erröten sehen, Zena!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Dommage ! J'aurais bien aimé te voir rougir, moi !"
L26_1.m_Talk_FRA = L27_1
