L34_1 = "어디서 그렇게 예쁜 드레스를 빌린 거야? 아이리 님한테도 알려주라~"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "どこでそんなにキレイなドレスを借りたの？　アイリ様にも教えてちょ～だい～。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Where did you find that beautiful dress? Please tell Irie!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "你從哪裡借來那麼漂亮的婚紗？快跟我說～"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ไปหาชุดสวยๆ นั่นมาจากไหนเหรอ? บอกไอรี่หน่อยสิ!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Chị tìm thấy cái váy xinh đẹp đó ở đâu vậy? Nói cho Irie đi mà!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "你是从哪儿借的那么漂亮的礼服？也告诉艾力一下呗~"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Wo hast du das schöne Kleid gefunden? Sag Irie bitte Bescheid!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Cette robe est trop belle ! Tu l'as trouvée où ? Dis-le moi pliiiiiiz !"
L33_1.m_Talk_FRA = L34_1
