L36_1 = "후후, 이건 빌린 게 아니라 제 거예요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "フフ、これは借りたものではなく自前です。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I didn’t find it, but I brought it from home."
L35_1.m_Talk_ENG = L36_1
L36_1 = "嘿嘿，這不是借的，是我自己的。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฉันไม่ได้หา แต่เอามาจากที่บ้านน่ะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Chị không tìm thấy nó, mà chị mang nó từ nhà đi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "嘿嘿，这个不是借的，是我自己的。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich habe es nicht gefunden, sondern ich habe es von zu Hause mitgebracht."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Je ne l'ai pas trouvée, je l'ai prise dans mon armoire."
L35_1.m_Talk_FRA = L36_1
