L37_1 = "CATHY_CIVIL_WEDDING_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "기자로 일할 때 이 이벤트를 취재했던 적이 있거든요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "記者の仕事をしていた時、このイベントを取材したことがあるんですよ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "There was a time when I covered this event as a reporter."
L36_1.m_Talk_ENG = L37_1
L37_1 = "我當記者的時候，曾經採訪過這個活動。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฉันเคยเป็นนักข่าวที่รายงานอีเวนต์นี้ครั้งหนึ่ง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Có một lần chị đã phát hiện ra sự kiện này khi là phóng viên."
L36_1.m_Talk_VTN = L37_1
L37_1 = "当记者的时候，我曾经采访过一个活动。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Es gab eine Zeit, in der ich als Reporter über dieses Ereignis berichtete."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Quand j'étais journaliste, il m'est arrivé de couvrir ce genre d'heureux évènement."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "SUMMER2021_ACT3_STAGE4_START@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3200307
L37_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "CATHY_CIVIL_WEDDING_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "이 드레스는 그 때 기념으로 선물 받은 거예요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "このドレスはあの時記念にプレゼントしてもらったものです。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "That’s when I got this dress as a gift."
L37_1.m_Talk_ENG = L38_1
L38_1 = "這件婚紗是那時候收到的禮物。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ตอนนั้นฉันได้ชุดนี้มาเป็นของขวัญ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đó là lúc chị nhận một món quà là chiếc váy này."
L37_1.m_Talk_VTN = L38_1
L38_1 = "这件礼服是那时收到的纪念礼物。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Da habe ich dieses Kleid geschenkt bekommen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Et une fois, on m'a même offert cette robe en cadeau."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "SUMMER2021_ACT3_STAGE4_START@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3200307
L38_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "CATHY_CIVIL_WEDDING_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "이 지역에서는 나름대로 큰 이벤트라 가져왔는데 역시나네요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "この地域ではそれなりに大きなイベントですし、持ってきたんです。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "This is quite a big event in this area, so I brought it just in case. And it was a good decision."
L38_1.m_Talk_ENG = L39_1
L39_1 = "這算是這個地方的大型活動，所以我就把它帶過來，果然我想的一樣。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "มันเป็นอีเวนต์ที่ค่อนข้างใหญ่แถวนี้น่ะ ฉันเลยหยิบชุดติดมาด้วย ซึ่งก็เป็นการตัดสินใจที่ดี"
L38_1.m_Talk_THA = L39_1
L39_1 = "Đây là một sự kiện khá lớn ở khu vực này, nên chị mang đi để đề phòng. Và thật đúng đắn."
L38_1.m_Talk_VTN = L39_1
L39_1 = "因为今天这个活动看起来很盛大的样子，我就带来了，果然派上用场了呢。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Dies ist ein recht großes Ereignis in dieser Region, also habe ich es für alle Fälle mitgebracht. Und es war eine gute Entscheidung."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Dans cette région, un mariage est un évènement de taille. J'ai pris ma robe au cas où, et il faut croire que je ne m'étais pas trompée !"
L38_1.m_Talk_FRA = L39_1
