L40_1.m_Pos = "C"
L41_1 = "설마…… 함선에 못 탈 뻔했던 것도 그 드레스 때문이었어?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "まさか……艦船の乗船時間ぎりぎりに来たのも、そのドレスのせい？"
