L41_1 = "I was wondering... You almost missed the ship because of this dress?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "該不會…你差點搭不上艦船，是因爲那件婚紗嗎？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ฉันสงสัยนะ... คุณเกือบขึ้นเรือไม่ทันเพราะชุดนี้รึเปล่า?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Em đang thắc mắc là... Chị suýt thì trễ tàu bởi vì chiếc váy này?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "你……差一点没赶上舰船不会也是因为这件礼服吧？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Ich frage mich ... hast du wegen dieses Kleides fast das Schiff verpasst?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Attends... C'est pour enfiler ça que tu as failli rater le bateau tout à l'heure ?"
