L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "L"
L46_1 = "저런 복장으로도 이벤트에 참가할 수 있는 거야?"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あんな服装でもイベントに参加できるの？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I didn’t know you could participate with a costume other than a wedding dress."
L45_1.m_Talk_ENG = L46_1
L46_1 = "穿那種服裝也能參加活動嗎？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ไม่ยักรู้ว่าเราเข้าร่วมงานได้โดยไม่จำเป็นต้องใส่ชุดแต่งงาน"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi không biết là có thể tham gia với trang phục khác ngoài váy cưới đấy."
L45_1.m_Talk_VTN = L46_1
L46_1 = "穿那种服装也能参加活动吗？"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich wusste nicht, dass man mit einem anderen Kostüm als einem Hochzeitskleid teilnehmen kann."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je ne savais pas qu'on pouvait participer en portant autre chose qu'une robe de mariée..."
L45_1.m_Talk_FRA = L46_1
