L47_1 = "Vậy thì, Irie sẽ mặc bộ đồ ngủ gấu trúc khổng lồ!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "那艾力也去换上无敌可爱的大熊猫睡衣再回来！"
