L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3200307
L50_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_Face = "UNIT_LAUGH"
L50_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L50_1.m_Pos = "R"
L51_1 = "이야, 다들 사이 좋은 신랑 신부들 같구만. 진짜 결혼식도 아닌데 나까지 다 가슴이 뛰는군."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "いやあ、みんな仲のいい新郎新婦みたいだな。本当の結婚式でもないのに私まで胸がドキドキしてしまう。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Oh, I see a lot of happy grooms and brides. They’re not actually getting married, but the excitement is genuine."
L50_1.m_Talk_ENG = L51_1
L51_1 = "哎呀，大家看起來都好像甜蜜的新人。明明就不是真的婚禮，搞得連我都心跳加速。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "มีเจ้าบ่าวกับเจ้าสาวที่มีความสุขเยอะเลย พวกเขาไม่ได้จะแต่งงานกันจริงๆ แต่ทุกคนตื่นเต้นกันจริงๆ นะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ồ, tôi nhìn thấy rất nhiều cô dâu và chú rể hạnh phúc. Họ không thực sự kết hôn, nhưng họ thật sự phấn khích."
L50_1.m_Talk_VTN = L51_1
L51_1 = "哎呀，大家都很像甜蜜恩爱的新郎新娘呢。即便不是真正的婚礼，我也跟着激动了。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Oh, ich sehe viele glückliche Bräutigame und Bräute. Sie heiraten nicht wirklich, aber die Aufregung ist echt."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Oh, regarde un peu tous ces gens en costumes de mariés, là-bas. Ils font peut-être semblant mais l'excitation est réelle, elle !"
L50_1.m_Talk_FRA = L51_1
