L1_1.m_Talk_ENG = L2_1
L2_1 = "真的，大家的表情都很幸福。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ใช่ค่ะ ทุกคนดูมีความสุข"
L1_1.m_Talk_THA = L2_1
L2_1 = "Đúng vậy. Mọi người đều có vẻ hạnh phúc."
