L2_1 = "是的。大家都一脸幸福的表情呢。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Ja. Alle scheinen glücklich zu sein."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Oui. Tout le monde semble heureux."
