L4_1 = "실례합니다. 코핀 컴퍼니의 사장님 맞으시죠?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "すみません。コフィンカンパニーの社長さんですよね？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Excuse me. Aren’t you the CEO of Coffin Company?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "請問你是科芬公司的老闆吧？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ขอโทษนะคะ คุณคือ CEO บริษัทคอฟฟินไม่ใช่เหรอคะ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Xin thứ lỗi. Ngài có phải là CEO của Công Ty Coffin không?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "冒昧地问一下，您是科芬公司的老板吧？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Verzeihung. Sind Sie nicht der CEO der Coffin Company?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Excusez-moi, mais... Vous ne seriez pas le directeur de la Compagnie Coffin, par hasard ?"
