L8_1 = "CATHY_CIVIL_WEDDING_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "L"
L8_1 = "오피셜 서포트 소속 캐시 웨이드입니다. 이런 곳에서 뵙다니 행운이네요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "オフィシャルサポート所属のキャシー・ウェイドです。こんなところでお会いできるなんて、光栄です。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Cathy Wade from Official Support. It’s so good to see you here."
L7_1.m_Talk_ENG = L8_1
L8_1 = "我是官方支援的凱西·韋德，竟然能在這種地方見到你，真是幸運。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เคธี่ เวดจากออฟฟิเชียลซัพพอร์ตค่ะ ดีใจที่ได้พบคุณที่นี่"
L7_1.m_Talk_THA = L8_1
L8_1 = "Cathy Wade từ Hỗ Trợ Chính Thức. Thật vui khi được gặp ngài ở đây."
L7_1.m_Talk_VTN = L8_1
L8_1 = "我是隶属于支援小队的凯西·韦德。很荣幸在这里见到您。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Cathy Wade von der Offiziellen Unterstützung. Es ist so schön, Sie hier zu sehen."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Cathy Wade, d'Official Support. Quel heureux hasard de vous retrouver ici."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "SUMMER2021_ACT3_STAGE4_START@108#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3200307
L8_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_LAUGH"
L8_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L8_1.m_Pos = "R"
L9_1 = "오, 반갑네. 듣기로는 최근 지원이 좀 늘어났다지."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "おお、こちらこそ。聞いた話では最近予算が増えたそうだな。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Oh, good to see you, too. I heard Official Support acquired a bigger budget recently."
L8_1.m_Talk_ENG = L9_1
L9_1 = "哦，很高興見到你。我聽說最近支援有增加喔。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "อ๊ะ ยินดีเช่นกันครับ ผมได้ยินมาว่าออฟฟิเชียลซัพพอร์ตเพิ่งได้งบก้อนใหญ่ขึ้นมาเมื่อเร็วๆ นี้"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ồ, tôi cũng rất vui khi được gặp cô. Tôi nghe nói Hỗ Trợ Chính Thức vừa nhận được một khoản lớn."
L8_1.m_Talk_VTN = L9_1
L9_1 = "噢，你好。我听说最近支援增加了一些。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Oh, auch schön, Sie zu sehen. Ich habe gehört, dass Sie kürzlich ein größeres Budget erhalten haben."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Oh, le plaisir est partagé. J'ai entendu dire que ton organisation a reçu des financements importants, récemment !"
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "SUMMER2021_ACT3_STAGE4_START@109#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3200307
L9_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "UNIT_PRIDE"
L9_1.m_Face = L10_1
L10_1 = "CATHY_CIVIL_WEDDING_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "L"
L10_1 = "후훗. 네, 여기서 이렇게 여유 부릴 정도로는요."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "フフッ。はい、おかげでこんなリゾート地にも来れるくらいにはなりました。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Yes, it was enough for us to have some time hanging out here."
L9_1.m_Talk_ENG = L10_1
L10_1 = "嘿嘿，是的，所以我才能在這裡悠閒快活。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ใช่ค่ะ มากพอที่จะทำให้พวกเรามีเวลาพักผ่อนอยู่ที่นี่"
L9_1.m_Talk_THA = L10_1
L10_1 = "Vâng, nó cũng đủ cho chúng tôi có thời gian đi chơi ở đây."
L9_1.m_Talk_VTN = L10_1
L10_1 = "嘿嘿。是，刚好够我们这样有一点闲暇时间的程度。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ja, es hat uns gereicht, um hier etwas Zeit zu verbringen."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oui, suffisamment pour nous permettre de passer un peu de temps ici, hé hé."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "SUMMER2021_ACT3_STAGE4_START@110#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3200307
L10_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "UNIT_PRIDE"
L10_1.m_Face = L11_1
L10_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L10_1.m_Pos = "R"
L11_1 = "그런데 캐시 양, 듣기로는 이 지역에서 원래 이맘 때쯤 어떤 행사가 열린다고 하던데……."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ところで、この地域ではこの時期にあるイベントが開かれるらしいが……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "By the way, Cathy, I heard they are holding some sort of event here."
L10_1.m_Talk_ENG = L11_1
L11_1 = "不過，我聽說這個地方，通常這個時候都會舉辦某個活動……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ว่าแต่ เคธี่ ผมได้ยินว่าที่นี่กำลังมีอีเวนต์"
L10_1.m_Talk_THA = L11_1
L11_1 = "Nhân tiện, Cathy, tôi nghe nói là họ đang tổ chức sự kiện gì đó ở đây."
L10_1.m_Talk_VTN = L11_1
L11_1 = "不过凯西，我听说这个地区每年这时候都会举办什么活动……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Übrigens, Cathy, ich habe gehört, dass hier um diese Saison eine Art Veranstaltung abgehalten wird."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Au fait, Cathy, j'ai entendu dire qu'on organisait un évènement spécial ici."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "SUMMER2021_ACT3_STAGE4_START@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3200307
L11_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L11_1.m_Pos = "R"
L12_1 = "보아하니 자네도 그 행사에 참가하려는 것 같군."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "どうやら君もそのイベントに参加するようだな。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I suppose you’re participating in the event as well?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "看來你也是要參加活動的吧？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "แปลว่าคุณคงเข้าร่วมด้วยงั้นสิครับ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi cho là cô cũng tham gia sự kiện này đúng không?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "你也是来参加那项活动的咯。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ich nehme an, Sie nehmen auch an der Veranstaltung teil?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Vu ton accoutrement, je suppose que tu participes également ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SUMMER2021_ACT3_STAGE4_START@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3200307
L12_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_SURPRISE"
L13_1 = "CATHY_CIVIL_WEDDING_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "L"
L13_1 = "비치 웨딩 콘테스트 말씀이시죠?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ビーチウェディングコンテストのことですね？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "You mean the Beach Wedding Contest?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "你是說沙灘婚紗照比賽吧？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "หมายถึงการประกวดแต่งงานริมหาดเหรอคะ?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Ý ngài là Cuộc Thi Đám Cưới Bãi Biển à?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "您说的是沙滩婚纱摄影大赛吧？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Sie meinen den Strand-Hochzeits-Wettbewerb?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Vous voulez parler du Concours de mariage de la plage, n'est-ce pas ?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SUMMER2021_ACT3_STAGE4_START@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3200307
L13_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_LAUGH"
L14_1 = "CATHY_CIVIL_WEDDING_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "L"
L14_1 = "맞아요. 원래 이 지역은 예전에 젊은 부부들의 신혼여행 코스로 유명했거든요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "はい、昔からこの地域は若い夫婦の新婚旅行先で有名だったんですよ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You’re right. This place used to be a very popular spot for newlyweds."
L13_1.m_Talk_ENG = L14_1
L14_1 = "沒錯，這個地方原本就是以蜜月勝地而聞名。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ใช่ค่ะ ที่นี่เคยเป็นสถานที่ยอดนิยมสำหรับคู่แต่งงานใหม่"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ngài nói đúng rồi. Địa điểm này rất nổi tiếng với những cặp đôi mới cưới."
L13_1.m_Talk_VTN = L14_1
L14_1 = "是的。因为这个地区原本是年轻夫妇度蜜月的著名路线。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Sie haben Recht. Dieser Ort war früher ein sehr beliebter Ort für Brautpaare."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Vous avez vu juste. Jadis, cette plage était un endroit très populaire pour les jeunes mariés."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "SUMMER2021_ACT3_STAGE4_START@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3200307
L14_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "CATHY_CIVIL_WEDDING_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "L"
L15_1 = "그래서 매년 젊은 신혼부부들을 대상으로 웨딩 사진을 찍어주는 이벤트가 열리곤 했어요."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "それで毎年、新婚夫婦を対象にウェディングフォトを撮るイベントが開かれているんです。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "So they used to hold a wedding photo event for visiting couples."
L14_1.m_Talk_ENG = L15_1
L15_1 = "因此每年都會以年輕的新婚夫婦爲對象，舉行拍婚紗照的活動。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "พวกเขาเคยจัดอีเวนต์ถ่ายรูปแต่งงานให้กับคู่รักที่มาเที่ยวที่นี่"
L14_1.m_Talk_THA = L15_1
L15_1 = "Nên họ tổ chức sự kiện chụp ảnh cưới cho các cặp đôi đến thăm quan."
L14_1.m_Talk_VTN = L15_1
L15_1 = "所以每年都会面向年轻的新婚夫妇举办拍婚纱照的活动。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Also gab es früher ein Hochzeitsfoto-Event für Paare auf Besuch."
L14_1.m_Talk_DEU = L15_1
L15_1 = "La tradition voulait que les couples en lune de miel y tiennent même des séances de photo sur la plage, devant le coucher du soleil..."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "SUMMER2021_ACT3_STAGE4_START@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3200307
L15_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "CATHY_CIVIL_WEDDING_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "L"
L16_1 = "촬영에 필요한 복장이나 소품도 누구에게나 빌려주고 말이죠."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "撮影に必要な服装や小物も貸し出したりしているそうですね。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "They also lend clothing and props for the photo shoot."
L15_1.m_Talk_ENG = L16_1
L16_1 = "也會出借拍照需要的服裝和道具給有需要的人。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แล้วก็มีชุดกับอุปกรณ์เสริมให้ยืมใช้ในการถ่ายรูปด้วยค่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Họ cũng cho thuê quần áo và vật dụng cho buổi chụp hình."
L15_1.m_Talk_VTN = L16_1
L16_1 = "还会借给所有人用来拍照的服装或道具。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Sie verleihen hier auch Kleidung und Requisiten für das Fotoshooting."
L15_1.m_Talk_DEU = L16_1
L16_1 = "À tel point qu'un système de location de costumes avait même été mis en place."
L15_1.m_Talk_FRA = L16_1
