L20_1 = "Vậy đây sẽ là <color=#ffd34c>nhiệm vụ bổ sung</color> của cô, Veronica."
L19_1.m_Talk_VTN = L20_1
L20_1 = "你的<color=#ffd34c>额外工作</color>我定好了，贝罗尼卡。"
