L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3200307
L20_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_LAUGH"
L20_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L20_1.m_Pos = "R"
L21_1 = "나와 함께 최고의 웨딩 사진을 찍어 비치 웨딩 콘테스트에 도전하는 걸세!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "私と一緒に最高のウェディングフォトを撮ってビーチウェディングコンテストに挑戦することだ！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "We’re going to take the best wedding photo ever, and participate in the Beach Wedding Contest!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "就是和我一起拍出最棒的婚紗照，挑戰沙灘婚紗照比賽！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เราจะถ่ายรูปแต่งงานที่สวยที่สุด แล้วลงประกวดแต่งงานริมหาดกัน!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Chúng ta sẽ chụp một bức ảnh cưới đẹp nhất từ trước đến nay và tham gia Cuộc Thi Đám Cưới Bãi Biển!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "那就是跟我一起拍摄最棒的婚纱照，然后参加沙滩婚纱摄影大赛！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wir werden zusammen das beste Hochzeitsfoto aller Zeiten schießen und am Strand-Hochzeits-Wettbewerb teilnehmen!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Tu vas poser avec moi, et nous prendrons la plus belle photo de mariage de tous les temps. Gagnons ce concours !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
