L23_1 = "SUMMER2021_ACT3_STAGE4_START@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3200307
L22_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Face = "UNIT_DESPAIR"
L22_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L22_1.m_Pos = "L"
L23_1 = "주인님. 제게 휴식을 주시려는 배려는 감사합니다만, 군중에게 노출되는 위협을 감수하실 건……."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ご主人様、私に休ませようという配慮はありがたいのですが、群衆に姿を晒すリスクを負うのは……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Master, I appreciate you trying to give me some time off, but it’s not a wise decision to show yourself in public..."
L22_1.m_Talk_ENG = L23_1
L23_1 = "主人，謝謝您想藉機讓我休息的好意，但我怕您拋頭露面會有危險……"
L22_1.m_Talk_TWN = L23_1
L23_1 = "นายท่าน ฉันยินดีที่คุณพยายามให้ฉันได้มีเวลาพักนะคะ แต่การที่คุณจะปรากฏตัวต่อสาธารณะไม่ใช่เรื่องที่ดีเลย..."
L22_1.m_Talk_THA = L23_1
L23_1 = "Chủ Nhân, tôi rất cảm kích việc ngài cố gắng để tôi nghỉ ngơi, nhưng việc thể hiện mình ở nơi công cộng không phải là một quyết định khôn ngoan..."
L22_1.m_Talk_VTN = L23_1
L23_1 = "主人，我很感谢您想安排我休息的心意，但甘愿暴露在群众的威胁之中……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Sir, ich weiß es zu schätzen, dass Sie versuchen, mir eine Auszeit zu verschaffen, aber es ist keine kluge Entscheidung, sich in der Öffentlichkeit zu zeigen ..."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Maître, je vois bien que vous essayez de me donner du temps libre, mais... je ne suis pas sûre qu'il soit très sage de vous présenter en public."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "SUMMER2021_ACT3_STAGE4_START@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3200307
L23_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_DESPAIR"
L23_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L23_1.m_Pos = "R"
L24_1 = "휴식이라니, 이건 자네를 위한 <color=#ffd34c>추가 업무</color>일세."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "休ませる？　いや、これは君のための<color=#ffd34c>追加業務</color>さ。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Time off? I told you, this is an <color=#ffd34c>additional task</color>."
L23_1.m_Talk_ENG = L24_1
L24_1 = "這才不是休息，這是爲你安排的<color=#ffd34c>額外工作</color>！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "เวลาพักเหรอ? ผมบอกแล้วไงว่านี่คือ<color=#ffd34c>งานเสริม</color>"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nghỉ ngơi? Tôi bảo cô rồi, đây là một <color=#ffd34c>nhiệm vụ bổ sung</color>."
L23_1.m_Talk_VTN = L24_1
L24_1 = "什么休息，这是我给你安排的<color=#ffd34c>额外工作</color>。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Eine Auszeit? Ich sage doch, dass dies eine <color=#ffd34c>zusätzliche Aufgabe</color> ist."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Du temps libre ? Je te l'ai dit, non ? Il s'agit d'une <color=#ffd34c>mission</color>."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "SUMMER2021_ACT3_STAGE4_START@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3200307
L24_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "UNIT_PRIDE"
L24_1.m_Face = L25_1
L24_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L24_1.m_Pos = "R"
L25_1 = "아주 피곤하고, 특별한 의미도 없고, 심지어 별도의 수당도 없는 성가신 업무."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "とても疲れるし特別な意味もなく、しかも別途の手当てもない煩わしい業務だ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "A task that is very tiresome, meaningless, and without payment."
L24_1.m_Talk_ENG = L25_1
L25_1 = "很累人，又有點沒意義，甚至沒有額外補助的麻煩事。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "งานที่เหนื่อยมาก ไร้ความหมาย และไร้ค่าตอบแทน"
L24_1.m_Talk_THA = L25_1
L25_1 = "Một nhiệm vụ rất mệt mỏi, vô nghĩa và không được trả tiền."
L24_1.m_Talk_VTN = L25_1
L25_1 = "非常累人，没什么特别的意义，甚至也没有单独津贴，很烦人的工作。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Eine Aufgabe, die sehr mühsam, sinnlos und ohne Bezahlung ist."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Une mission ennuyeuse, fastidieuse... et non rémunérée."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "SUMMER2021_ACT3_STAGE4_START@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3200307
