L28_1 = "SUMMER2021_ACT3_STAGE4_START@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3200307
L27_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_IDLE"
L27_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "하지만 시간이 지나고 나면, 그런 일이 가장 기억에 남을 때도 있지."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "しかし時間が経てば、そういう出来事が一番記憶に残る時もある。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "But accomplishing such a task can be much more memorable."
L27_1.m_Talk_ENG = L28_1
L28_1 = "可是等到日後，你可能才會發現，原來那才是最令你難忘的回憶。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "แต่การทำงานแบบนี้ให้สำเร็จอาจเป็นสิ่งที่น่าจดจำมากๆ นะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nhưng hoàn thành một nhiệm vụ như vậy có thể rất đáng nhớ."
L27_1.m_Talk_VTN = L28_1
L28_1 = "可是随着时间流逝，这些事也会成为印象最深刻的回忆。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Aber das Erfüllen einer solchen Aufgabe kann viel länger in Erinnerung bleiben."
L27_1.m_Talk_DEU = L28_1
L28_1 = "En revanche, cette mission te laissera un souvenir impérissable. Que tu chériras encore plus avec le temps."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "SUMMER2021_ACT3_STAGE4_START@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3200307
L28_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_LAUGH"
L28_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L28_1.m_Pos = "C"
L29_1 = "그러니 자네가 도와 주길 바라네. 이 곳에서 아주 사소한 기억을 남길 수 있게 말이야."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "だから君にはぜひ手伝ってもらいたい。ここでとても些細な思い出が残せるように。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "So I would like you to help me create good memories to look back on."
L28_1.m_Talk_ENG = L29_1
L29_1 = "所以希望你能幫忙，在這裡留下小小的回憶。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ดังนั้นผมถึงอยากให้คุณช่วยผมสร้างความทรงจำดีๆ ให้มองย้อนกลับมา"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nên tôi muốn cô giúp tôi tạo ra một hồi ức đẹp đáng nhớ.."
L28_1.m_Talk_VTN = L29_1
L29_1 = "所以希望你能帮忙，帮我在这个地方留下点点滴滴的回忆。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Deshalb möchte ich, dass Sie mir helfen, schöne Erinnerungen zu sammeln, auf die ich zurückblicken kann."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Alors, tu veux bien m'aider à faire de cette journée un moment inoubliable ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
