L33_1 = "SUMMER2021_ACT3_STAGE4_START@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3200307
L32_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L32_1.m_Pos = "L"
L33_1 = "알겠습니다. 이곳에서 경호를 수행하기에는 웨딩 드레스가 눈에 덜 띄겠군요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "承知しました。ここで警護を遂行するにはウェディングドレスの方が目立たなさそうですね。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I understand. I suppose changing to a wedding dress will be better to operate in this area."
L32_1.m_Talk_ENG = L33_1
L33_1 = "好吧，穿著婚紗混在人群中也比較不顯眼。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เข้าใจแล้วค่ะ ฉันว่าการเปลี่ยนไปใส่ชุดแต่งงานคงทำให้ดูกลมกลืนกับคนแถวนี้ได้มากกว่า"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi hiểu rồi. Tôi cho rằng thay đồ sang váy cưới sẽ hoạt động tốt hơn ở khu vực này."
L32_1.m_Talk_VTN = L33_1
L33_1 = "我知道了。在这个地方，穿着婚纱执行警卫工作应该反倒没那么显眼。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich verstehe. Ich nehme an, in einem Hochzeitskleid werde ich Sie hier unauffälliger bewachen können."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Je comprends. Dans ce cas, je suppose que je ferais mieux de mettre une tenue plus... appropriée."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SUMMER2021_ACT3_STAGE4_START@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3200307
L33_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L33_1.m_Pos = "L"
L34_1 = "다만, 업무 사항에 대해 한 가지 말씀드려도 되겠습니까?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ただ、業務事項について一つだけ申し上げてもよろしいでしょうか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "However... May I say a word about the task?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "不過，有件是我想主人說清楚，可以嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แต่ว่า... ขอฉันพูดอะไรเกี่ยวกับงานนี้หน่อยได้มั้ยคะ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tuy nhiên... Tôi có thể nói một câu về nhiệm vụ không?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "不过，对于工作事项，我可以说一件事吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Aber ... Dürfte ich ein Wort zur Aufgabe sagen?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Cependant, m'autorisez-vous à ajouter quelque chose ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "SUMMER2021_ACT3_STAGE4_START@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3200307
L34_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L34_1.m_Pos = "R"
L35_1 = "말해보게."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "なんでも言ってくれ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Go ahead."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你請說。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ว่ามาสิครับ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Nói đi."
L34_1.m_Talk_VTN = L35_1
L35_1 = "你说。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Bitte sehr."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Je t'écoute."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "SUMMER2021_ACT3_STAGE4_START@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3200307
L35_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "UNIT_PRIDE"
L35_1.m_Face = L36_1
L35_1.m_CharStrID = "LEADER_MAID_NULL_NULL"
L35_1.m_Pos = "L"
L36_1 = "저에게 있어…… 주인님을 모시기 위한 일은 결코 성가실 수 없습니다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "私にとって…… ご主人様に仕えることは決して煩わしいことではありません。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "To me, serving you is neither tiresome nor meaningless."
L35_1.m_Talk_ENG = L36_1
L36_1 = "對我來說… 只要是侍奉主人的事，就絕對不會是麻煩事。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "สำหรับฉัน การรับใช้คุณไม่มีน่าเหน็ดเหนื่อยหรือไร้ความหมายค่ะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Với tôi, phục vụ ngài chưa lúc nào là mệt mỏi hay vô nghĩa."
L35_1.m_Talk_VTN = L36_1
L36_1 = "对我来说……侍奉主人的工作绝对不是什么烦人的事。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ihnen zu dienen ist für mich weder ermüdend noch sinnlos."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Pour moi... Vous servir n'a jamais été ennuyeux, ni fastidieux. C'est même le contraire."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "SUMMER2021_ACT3_STAGE4_START@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3200307
L36_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_LAUGH"
L36_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L36_1.m_Pos = "R"
L36_1.m_Crash = 20
L37_1 = "하하. 기억하도록 하지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ハハハ、覚えておこう。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Hah hah. I’ll remember that."
L36_1.m_Talk_ENG = L37_1
L37_1 = "哈哈，我會牢記在心。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฮ่าๆ ผมจะจำเอาไว้นะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ha ha. Tôi sẽ nhớ điều đó."
L36_1.m_Talk_VTN = L37_1
L37_1 = "哈哈，我记下了。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Hahaha. Ich behalte mir das im Hinterkopf."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Ha ha. Je m'en souviendrai."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
