L38_1.m_Face = "UNIT_LAUGH"
L39_1 = "IRIE_CIVIL_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L38_1.m_Crash = 20
L39_1 = "앗, 사장님네도 콘테스트에 참가하게?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "お、社長たちも参加するの？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Oh, you’re participating in the contest as well?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "老闆你們也要參加比賽嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "อ๊ะ คุณก็จะลงประกวดด้วยเหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Ồ, chị cũng tham gia cuộc thi ư?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "啊，老板也要参加摄影大赛吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Oh, Sie nehmen auch am Wettbewerb teil?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Hé, tu vas participer au concours toi aussi, le directeur ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "SUMMER2021_ACT3_STAGE4_START@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3200307
L39_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "IRIE_CIVIL_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "그치만 웨딩 드레스는 안 될 걸? 아이리 님도 몸에 꼭 맞는 드레스를 못 구했다구?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "でもウェディングドレスじゃなきゃダメだよ。アイリ様だってサイズに合うドレスが見つからないもん。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "But you’ll never find the right dress for you. Even Irie failed to find one."
L39_1.m_Talk_ENG = L40_1
L40_1 = "但找不到合適的婚紗吧？艾莉也沒找到。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "แต่คุณไม่มีทางเจอชุดที่เหมาะกับตัวเองแน่ ขนาดไอรี่ยังหาไม่ได้เลย"
L39_1.m_Talk_THA = L40_1
L40_1 = "Nhưng chị sẽ không bao giờ tìm thấy cái váy phù hợp với mình. Đến cả Irie cũng thất bại."
L39_1.m_Talk_VTN = L40_1
L40_1 = "不过礼服估计不行呢。艾力也没能找到合适尺码的礼服呢？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Aber Sie werden nie das richtige Kleid für sich finden. Nicht einmal Irie fand einen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Et tu comptes faire comment ? Y'a plus une robe de disponible, même moi j'ai pas pu trouver la mienne !"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "SUMMER2021_ACT3_STAGE4_START@140#Talk"
