L40_1.m_Pos = "C"
L40_1.m_Crash = 20
L41_1 = "그거라면 걱정하지 말게나. 준비는 이미 끝났으니까."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "それなら心配ない。準備はもう出来ている。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Don’t worry about the dress. It’s all ready."
L40_1.m_Talk_ENG = L41_1
L41_1 = "這個不用擔心，我早就準備好囉～"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ไม่ต้องห่วงเรื่องชุดหรอก ผมเตรียมเอาไว้แล้วละ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Đừng lo về cái váy. Mọi thứ sẵn sàng rồi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "那个不用担心，因为我都已经准备好了。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Machen Sie sich keine Sorgen um das Kleid. Es steht alles bereit."
L40_1.m_Talk_DEU = L41_1
L41_1 = "La robe n'est pas un problème, j'ai déjà tout préparé."
L40_1.m_Talk_FRA = L41_1
