L45_1 = "쳇, 열등한 생쥐들 주제에 어딜 가나 다들 행복해 죽을 것만 같은 표정이군."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "ちっ、劣等なネズミどものくせに、どこへ行ってもどいつもこいつも幸せそうな顔をしてやがる。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Dang, those inferior rats look so happy everywhere."
L44_1.m_Talk_ENG = L45_1
L45_1 = "嗟，這些討厭鬼，不管去到哪都一副幸福的表情。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "บ้าจริง พวกหนูชั้นต่ำนี่ดูมีความสุขกันทุกที่เลย"
L44_1.m_Talk_THA = L45_1
L45_1 = "Trời, những con chuột kém cỏi đó trông thật hạnh phúc ở khắp mọi nơi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "切，一群低等老鼠，走到哪儿都是一副幸福得要死的表情呢。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Verdammt, diese minderwertigen Ratten sehen überall so glücklich aus."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Tss... ces rats inférieurs dégoulinent d'un bonheur infect."
L44_1.m_Talk_FRA = L45_1
