L45_1.m_Face = "UNIT_IDLE"
L46_1 = "LONELY_NPC_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "다들 그대로 혀 깨물고 콱 죽어버렸으면 좋겠는데 말이야……."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "みんなそのまま足を滑らせて崖から落ちればいいのに……"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I hope they all get struck by lightning..."
L45_1.m_Talk_ENG = L46_1
L46_1 = "真希望他們出門踩到狗屎，吃東西咬到舌頭……"
L45_1.m_Talk_TWN = L46_1
L46_1 = "อยากให้พวกมันถูกฟ้าผ่าตายจริงๆ..."
L45_1.m_Talk_THA = L46_1
L46_1 = "Mình mong là chúng bị sét đánh..."
L45_1.m_Talk_VTN = L46_1
L46_1 = "真希望所有人都咬舌自尽……"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich hoffe, sie werden alle vom Blitz getroffen..."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je voudrais qu'ils soient tous frappés par la foudre, tiens !"
L45_1.m_Talk_FRA = L46_1
