L47_1.m_Face = "UNIT_DESPAIR"
L48_1 = "LONELY_NPC_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L47_1.m_Crash = 25
L48_1 = "이런 조잡한 발상……. 삼류 악당이나 떠올릴 생각이야."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "こんな粗雑な発想は……三流悪党レベルの考え方だ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Such a pathetic wish... It’s for third-rate villains."
L47_1.m_Talk_ENG = L48_1
L48_1 = "這種惡質的詛咒……完全是三流反派的做法。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ปรารถนาอะไรน่าสมเพชแบบนี้... มีแต่วายร้ายเกรดต่ำเท่านั้นละที่จะคิดได้"
L47_1.m_Talk_THA = L48_1
L48_1 = "Đúng là một ước mong thảm hại... Nó dành cho một phản diện loại ba."
L47_1.m_Talk_VTN = L48_1
L48_1 = "这种卑劣的想法……是三流反派才会有的。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Solch ein erbärmlicher Wunsch ... ist für drittklassige Schurken."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Un souhait si pathétique... C'est vraiment pour les méchants de troisième zone."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "SUMMER2021_ACT3_STAGE4_START@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3200307
L48_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "LONELY_NPC_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "진정하자. 지금은 안전한 곳을 찾아서 새로운 레시피 연구를……."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "落ち着こう。今は安全な場所を見つけて、新しいレシピの研究を……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I have to stay calm. I have to find somewhere safe to work on my new recipes..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "冷靜點隆利！還是先找個安全的地方，研究新的食譜……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันต้องนิ่งเข้าไว้ ฉันต้องหาที่ปลอดภัยสำหรับคิดสูตรผสมใหม่..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Mình phải bình tĩnh. Mình phải tìm nơi nào đó an toàn để tiếp tục công thức mới của mình..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "冷静点。现在先找找安全的地方，开始研究新的配方……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich muss ruhig bleiben. Ich muss einen sicheren Ort finden, um an meinen neuen Rezepten zu arbeiten ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Reprends-toi, Solee ! Je dois trouver un endroit sûr pour travailler sur mes nouvelles recettes..."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
