L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3200307
L13_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L13_1.m_bWaitClick = true
