L14_1 = "LONELY_NPC_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "흐, 흥. 어리석은 것들. 그렇게 꼬리 친다고 우리 선배님이 쉽게 넘어가실 것 같아?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ふ、ふん、バカな連中。そんな風にしっぽを振ってれば先輩を簡単に落とせるとでも？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "H-hmpf! Pathetic women. Flirt as much as you like, Dark will never love you."
L13_1.m_Talk_ENG = L14_1
L14_1 = "哼哼，可惡的狐狸精！你以為我的前輩會那麼輕易上當嗎？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฮะ-ฮึ่ม! พวกผู้หญิงน่าสมเพช เชิญอ่อยเต็มที่เลย ดาร์กไม่มีวันรักพวกเธอหรอก"
L13_1.m_Talk_THA = L14_1
L14_1 = "Hừm! Những đứa con gái thảm hại. Tán tỉnh bao nhiêu tùy thích. Dark sẽ không bao giờ yêu các người."
L13_1.m_Talk_VTN = L14_1
L14_1 = "嗬，哼。这些愚蠢的家伙。以为凭借这样搔首弄姿的勾引，前辈就会轻易上钩吗？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "H-hmpf! Erbärmlich. Flirtet so viel ihr wollt, Dark wird euch nie lieben."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Peuh ! Quels êtres pathétiques. Flirtez autant que vous le souhaitez, Dark ne vous aimera jamais."
L13_1.m_Talk_FRA = L14_1
