L23_1.m_fTalkTime = 0.03
L24_1 = "ここからじゃ、ちゃんと聞こえないな。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I can’t hear them from here."
L23_1.m_Talk_ENG = L24_1
L24_1 = "聽不清楚他們在說什麼。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฟังตรงนี้ไม่ได้ยินเลย"
L23_1.m_Talk_THA = L24_1
L24_1 = "Mình không thể nghe họ nói chuyện từ đây."
L23_1.m_Talk_VTN = L24_1
L24_1 = "在这儿听不清在说什么呢。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich kann sie von hier aus nicht hören."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Je ne peux pas les entendre d'ici."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "SUMMER2021_ACT3_STAGE4_START@174#Talk"
