L25_1 = "LONELY_NPC_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L24_1.m_Crash = 15
L25_1 = "어, 어쩌지……? 들키지 않게 조금 더 가까이 가 볼까?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ど、どうしよう……？　バレないようにしてもっと近づいてみようかな？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "W-what do I do? Shall I go closer?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "怎…怎麼辦？在不被發現的前提下，要再靠近一點點嗎？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ทะ-ทำไงดี? เข้าไปใกล้กว่านี้ดีมั้ย?"
L24_1.m_Talk_THA = L25_1
L25_1 = "M-mình nên làm gì? Mình có nên lại gần hơn không?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "怎、怎么办呢……？要不要悄悄地再靠近一些呢？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "W-was soll ich tun? Soll ich näher ran?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Que dois-je faire ? Dois-je m'approcher ?"
L24_1.m_Talk_FRA = L25_1
