L28_1 = "……자, 그럼 베로니카 양. 준비는 되었나?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "……さあ、ベロニカ。準備はいいか？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "... So, Veronica. Are you ready?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "…貝洛妮卡，你準備好了嗎？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "...เอาละ เวโรนิกา คุณพร้อมรึยังล่ะ?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Veronica. Cô đã sẵn sàng chưa?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "……好了，贝罗尼卡，准备好了吗？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Also, Veronica. Sind Sie bereit?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "... Alors, Veronica ? Tu es prête ?"
