L37_1 = 30
L36_1.m_Crash = L37_1
L37_1 = "역시 내 예상대로야. 무척 잘 어울리는구만."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "やはり私の予想どおりだ。とても似合っている。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "It’s as I expected. You look very good in the dress."
L36_1.m_Talk_ENG = L37_1
L37_1 = "跟我想的一樣，很合適你。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "อย่างที่คิดไว้เลย คุณดูดีมากในชุดเจ้าสาวนะ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Như tôi đã mong đợi. Cô trong rất đẹp trong chiếc váy đó."
L36_1.m_Talk_VTN = L37_1
L37_1 = "果然跟我想的一样，很适合你。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Es ist so, wie ich es erwartet habe. Sie sehen sehr gut aus in dem Kleid."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Exactement ce que j'imaginais. Cette robe te va vraiment à ravir."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "SUMMER2021_ACT3_STAGE4_START@187#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 187
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3200307
L37_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "LEADER_FLORA_WEDDING_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "R"
L38_1 = "이런 옷은……. 저도 처음이군요. 점잖치 못한 차림이지만 부디 이해해 주시길."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "このような服は……私も初めてです。メイドらしくない格好ですが、どうぞご容赦ください。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I’ve never worn anything like this... It’s a bit indecent, but I hope you understand."
L37_1.m_Talk_ENG = L38_1
L38_1 = "這種衣服……我也是第一次穿。雖然有點不得體，但希望大家體諒。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ฉันไม่เคยสวมอะไรแบบนี้เลยค่ะ... มันไม่เหมาะสมนิดหน่อย แต่หวังว่าคุณจะเข้าใจนะคะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tôi chưa bao giờ mặc bất cứ thứ gì như thế này... Nó hơi khiếm nhã, nhưng tôi mong là ngài hiểu."
L37_1.m_Talk_VTN = L38_1
L38_1 = "这种衣服……我也是第一次穿。装扮不够雅观，请您见谅。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich habe so etwas noch nie getragen ... Es ist ein bisschen unanständig, aber ich hoffe, Sie haben Verständnis."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Je n'ai jamais rien porté de tel... C'est un peu indécent, j'espère que vous ne m'en voulez pas trop ?"
L37_1.m_Talk_FRA = L38_1
