L41_1 = "UNIT_HATE"
L40_1.m_Face = L41_1
L41_1 = "m_fFlashBangTime"
L40_1[L41_1] = 0.5
L41_1 = "FX_COMBAT_ALL_MAGIC_SPELL_LIGHT"
L40_1.m_StartFXSoundName = L41_1
L41_1 = "LONELY_NPC_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "잠깐, 신부복이라면 설마……. 선배님의 결혼 상대……?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "まって、ウェディングドレスならまさか……先輩の結婚相手？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Wait, a wedding dress? Is she’s getting married to Dark?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "等等，她穿的是婚紗，難道……她是前輩的未婚妻……？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เดี๋ยวนะ ชุดแต่งงานเหรอ? หล่อนจะแต่งงานกับดาร์กเหรอ?"
L40_1.m_Talk_THA = L41_1
L41_1 = "Chờ đã, một cái váy cưới? Cô ta chuẩn bị kết hôn với Dark à?"
L40_1.m_Talk_VTN = L41_1
L41_1 = "等等，新娘服的话……难道是前辈的结婚对象……？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Warte, ein Hochzeitskleid? Wird sie Dark heiraten?"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Une seconde ! Une robe de mariée ? Elle va se marier avec Dark ?"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "SUMMER2021_ACT3_STAGE4_START@191#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3200307
L41_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_SERIOUS"
L42_1 = "LONELY_NPC_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L41_1.m_Crash = 20
L42_1 = "그, 그럴 리 없어! 선배님이 나한테 한마디 말도 없이!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "そ、そんなはずない！　先輩が私に何も言わずにそんなこと！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "That’s... i-impossible! Dark would have told me!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "這…怎麼可能！前輩從來沒跟我提過她！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "นั่น... ปะ-เป็นไปไม่ได้! ดาร์กต้องบอกฉันสิ!"
L41_1.m_Talk_THA = L42_1
L42_1 = "K-không thể nào! Thế thì Dark sẽ nói với mình!"
L41_1.m_Talk_VTN = L42_1
L42_1 = "不、不可能！前辈也没告诉我一声！"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Das ist ... u-unmöglich! Dark hätte es mir gesagt!"
L41_1.m_Talk_DEU = L42_1
L42_1 = "C'est... impossible ! Dark m'en aurait forcément parlé !"
L41_1.m_Talk_FRA = L42_1
