L50_1 = "SUMMER2021_ACT3_STAGE4_START@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3200307
L49_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "LONELY_NPC_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "나 같은 음침녀가 저렇게 눈부시게 빛나는 여자를 이길 수 있을 리 없잖아. "
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "私みたいな陰気な女が、あんなにキラキラしている女に勝てるはずがない。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "A creepy woman like me could never beat her. She’s too beautiful..."
L49_1.m_Talk_ENG = L50_1
L50_1 = "像我這種陰沉女，怎麼可能贏過那種人美心善的正妹。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ผู้หญิงหลอนๆ อย่างฉันคงสู้หล่อนไม่ได้หรอก สวยซะขนาดนั้น..."
L49_1.m_Talk_THA = L50_1
L50_1 = "Một người phụ nữ đáng sợ như mình không bao giờ có thể đánh bại cô ấy. Cô ấy quá đẹp..."
L49_1.m_Talk_VTN = L50_1
L50_1 = "像我这种阴沉的样子，根本不可能赢过那么明媚动人的女人。 "
L49_1.m_Talk_SCN = L50_1
L50_1 = "Eine gruselige Frau wie ich könnte niemals gegen sie ankommen. Sie ist zu schön ..."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Une laideur comme moi ne pourra jamais la battre. Elle est trop belle..."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "SUMMER2021_ACT3_STAGE4_START@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3200307
L50_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "LONELY_NPC_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "내, 내가 선배님이었어도…… 나 같은 것보다……."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "わ、私が先輩の立場でも……私なんかより……"
L50_1.m_Talk_JPN = L51_1
L51_1 = "E-even I would have chosen her... over me..."
L50_1.m_Talk_ENG = L51_1
L51_1 = "如…如果我是前輩…我也會……"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ตะ-ต่อให้เป็นฉันก็คงเลือกผู้หญิงคนนี้... แทนที่จะเป็นฉัน..."
L50_1.m_Talk_THA = L51_1
L51_1 = "K-kể cả mình cũng sẽ chọn cô ấy... thay vì chọn mình..."
L50_1.m_Talk_VTN = L51_1
L51_1 = "如、如果我是前辈……也会选她而不选我……"
L50_1.m_Talk_SCN = L51_1
L51_1 = "S-selbst ich würde sie ... mir gegenüber vorziehen ..."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Franchement... Même moi je l'aurais choisie, si j'étais Dark."
L50_1.m_Talk_FRA = L51_1
