L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "몸도, 마음도 져 버렸어."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "身体も、中身も負けている。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "I’m lost... both in terms of mind and body."
L9_1.m_Talk_ENG = L10_1
L10_1 = "身材和心腸都比不過人家！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉันแพ้แล้ว... ทั้งร่ายกายและจิตใจ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Mình thua rồi... cả về thể xác lẫn tâm hồn."
L9_1.m_Talk_VTN = L10_1
L10_1 = "身心都输了。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ich habe verloren ... sowohl in Bezug auf den Geist als auch auf den Körper."
L9_1.m_Talk_DEU = L10_1
