L11_1 = "いや、最初から勝負にもならなかった。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "No. There was no competition in the first place."
L10_1.m_Talk_ENG = L11_1
L11_1 = "不對，從一開始就沒有所謂的勝負！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ไม่ เราไม่เคยแข่งกันตั้งแต่แรกแล้ว"
L10_1.m_Talk_THA = L11_1
L11_1 = "Không. Từ đầu đã không có sự cạnh tranh nào cả."
L10_1.m_Talk_VTN = L11_1
L11_1 = "不。从一开始，这件事就不存在输赢的说法。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Nein. Es gab nie einen Wettbewerb."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Attends, qu'est-ce que j'imagine ? Il n'y a jamais eu de compétition."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "SUMMER2021_ACT3_STAGE4_START@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 3200307
L11_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_DESPAIR"
L12_1 = "LONELY_NPC_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L11_1.m_Crash = 15
L12_1 = "그 여자는…… 나 같은 게 있는 줄도 모를 테니까."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "あの女は……私の存在すら知らないから。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "She doesn’t even know... that I exist."
L11_1.m_Talk_ENG = L12_1
L12_1 = "那個女生……說不定根本不知道我這個東西的存在呢！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "หล่อนไม่รู้ด้วยซ้ำ... ว่าฉันมีตัวตน"
L11_1.m_Talk_THA = L12_1
L12_1 = "Cô ấy thậm chí còn không biết... là mình tồn tại."
L11_1.m_Talk_VTN = L12_1
L12_1 = "那个女人……可能都不知道我的存在。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Sie weiß nicht einmal, dass ich existiere."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Cette femme... Elle ne sait même pas que j'existe."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SUMMER2021_ACT3_STAGE4_START@212#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 212
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3200307
L12_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "LONELY_NPC_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "그냥 나 혼자 멋대로 선배님을 좋아하고, 나 혼자 멋대로 기뻐했고, 나 혼자 멋대로 슬퍼할 뿐……."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "私一人で勝手に先輩のことが好きになって、一人で勝手に喜んで、一人で勝手に悲しむだけ……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I loved him by myself, I was happy just by myself. And now I’m sad all by myself..."
L12_1.m_Talk_ENG = L13_1
L13_1 = "是我一廂情願地喜歡前輩，一廂情願地開心，一廂情願地難過……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฉันรักเขาแบบเงียบๆ มีความสุขกับตัวเอง แล้วตอนนี้ก็เศร้าอยู่คนเดียว..."
L12_1.m_Talk_THA = L13_1
L13_1 = "Mình yêu đơn phương anh ấy, và hạnh phúc một mình. Và giờ mình lại tự mình buồn..."
L12_1.m_Talk_VTN = L13_1
L13_1 = "就是我独自喜欢前辈，独自开心，独自伤心而已……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich liebte ihn allein, ich war allein glücklich. Und jetzt bin ich ganz allein traurig ..."
L12_1.m_Talk_DEU = L13_1
L13_1 = "J'aimais Dark dans mon coin. J'étais heureuse, seule. Et maintenant je suis triste, seule."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SUMMER2021_ACT3_STAGE4_START@213#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 213
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 3200307
L13_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "UNIT_HATE"
L13_1.m_Face = L14_1
L14_1 = "LONELY_NPC_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L13_1.m_Crash = 50
L14_1 = "역시 나 같은 건…… 나 같은 건……!!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "やっぱり私なんか……私なんか……！！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I’m so useless... so pathetic..."
L13_1.m_Talk_ENG = L14_1
L14_1 = "像我這種…像我這種東西……！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฉันช่างไร้ประโยชน์... น่าสมเพช..."
L13_1.m_Talk_THA = L14_1
L14_1 = "Mình thật vô dụng... thật thảm hại..."
L13_1.m_Talk_VTN = L14_1
L14_1 = "果然像我这样的人……像我这样的人……！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich bin so nutzlos ... so erbärmlich ..."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Je suis si inutile... si pathétique..."
L13_1.m_Talk_FRA = L14_1
