L16_1 = "SUMMER2021_ACT3_STAGE4_START@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3200307
L15_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_SERIOUS"
L15_1.m_StartBGMFileName = "THEMA_SUMMER_02"
L16_1 = "ROSARIA_FALLEN_WEDDING_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L15_1.m_Crash = 20
L16_1 = "내 예상대로 삼류 조연처럼 청승이란 청승은 다 떨고 있군."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "妾の予想どおり、三流脇役のように哀れな振る舞いをしているな。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I knew it. You’re playing the victim as if you’re a third-rate supporting character in a love story."
L15_1.m_Talk_ENG = L16_1
L16_1 = "就跟我想一樣，像個路人甲一樣在那自怨自艾。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "กะแล้วเชียว เจ้าเล่นบทเหยื่ออย่างกับตัวละครประกอบเกรดต่ำในหนังรักเลยนะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Biết ngay mà. Cô lại đóng vai nạn nhân như thể cô là nhân vật hỗ trợ hạng ba trong phim tình cảm."
L15_1.m_Talk_VTN = L16_1
L16_1 = "果真像我预想的那样，你跟个三流配角似的凄惨到家了呢。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich wusste es. Du spielst das Opfer, als wärst du eine drittklassige Nebenfigur in einer Liebesgeschichte."
L15_1.m_Talk_DEU = L16_1
L16_1 = "C'est bien ce que je pensais. Tu joues la victime comme un personnage secondaire de troisième zone dans une comédie à l'eau de rose."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "SUMMER2021_ACT3_STAGE4_START@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3200307
L16_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_SURPRISE"
L17_1 = "LONELY_NPC_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "C"
L16_1.m_Crash = 10
L17_1 = "로, 로자리아…… 님? 그 복장은 대체 뭐죠?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ロ、ロザリアさん……？　その格好はどうしたんですか？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "R-Rosaria? What are you wearing?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "羅…羅莎莉亞…？為什麼你也穿著婚紗？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ระ-โรซาเลีย? สวมชุดอะไรของเธอน่ะ?"
L16_1.m_Talk_THA = L17_1
L17_1 = "R-Rosaria? Cô đang mặc cái gì vậy?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "罗、罗莎莉亚……？你那个服装是怎么回事？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "R-Rosaria? Was trägst du da?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "R-Rosaria ? Qu'est-ce que vous portez ?"
L16_1.m_Talk_FRA = L17_1
