L20_1 = "SUMMER2021_ACT3_STAGE4_START@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 3200307
L19_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "UNIT_PRIDE"
L19_1.m_Face = L20_1
L20_1 = "ROSARIA_FALLEN_WEDDING_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "R"
L20_1 = "후훗. 어리석구나. 이 모습을 보고도 모르겠느냐."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "フフ、愚か者よ。見ればわかるじゃろ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Hah hah. You foolish girl. Can’t you see?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "呵呵，你眼睛有問題嗎？這樣還看不出來嗎。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฮ่าๆ ยัยโง่ ดูไม่ออกรึไง?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ha ha. Đồ ngốc. Cô không thấy sao?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "嘿嘿，你这个笨蛋。看到这些还不明白吗。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Hahaha. Du dummes Mädchen. Kannst du nicht sehen?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Ha ha. Imbécile. Tu ne comprends pas ?"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "SUMMER2021_ACT3_STAGE4_START@220#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 220
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 3200307
L20_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_StartFXSoundName = "FX_CUTSCEN_TADA"
L21_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "R"
L20_1.m_Crash = 15
L21_1 = "지금의 나는 세계 제일의 신부님이자, <color=#ffd34c>파혼과 치정의 마왕</color>님이니라!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "今の妾は世界一の花嫁であり、<color=#ffd34c>破婚と痴情の魔王</color>なのじゃ！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I am the best bride in the world, and the <color=#ffd34c>Homewrecker Demon Lord of Illicit Love</color>!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "現在的我是世界最美的新娘，也是 <color=#ffd34c>解除婚約和癡情魔王</color>！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ข้าเป็นเจ้าสาวที่ดีที่สุดในโลก และเป็น<color=#ffd34c>เจ้าแห่งดีม่อนจอมทำลายครอบครัวแห่งรักที่ผิดศีลธรรม</color>ไงล่ะ!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi là cô dâu tuyệt nhất thế giới, và là <color=#ffd34c>Chúa Quỷ Kẻ Phá Hoại Gia Đình và Tình Yêu Bất Chính</color>!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "现在的我是世界第一的新娘，也是<color=#ffd34c>退婚和婚外情魔王</color>！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich bin die beste Braut der Welt und die <color=#ffd34c>Ehebrecher-Dämonenfürstin der Verbotenen Liebe</color>!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Je suis la meilleure épouse du monde, le <color=#ffd34c>Démon séducteur et briseur de fiançailles</color> !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
