L21_1.m_fWaitTime = 0
L22_1 = "LONELY_NPC_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "L"
L22_1 = "파혼과…… 치정의 마왕?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "破婚と……痴情の魔王？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Homewrecker Demon Lord of Illicit Love?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "解除婚約和… 癡情魔王？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เจ้าแห่งดีม่อนจอมทำลายครอบครัวแห่งรักที่ผิดศีลธรรมเหรอ?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Chúa Quỷ của Phá Hoại Hôn Nhân và Tình Yêu Bất Chính?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "退婚和……婚外情魔王？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ehebrecher-Dämonenfürstin der Verbotenen Liebe ...?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Démon séducteur et... briseur de fiançailles ?"
L21_1.m_Talk_FRA = L22_1
