L23_1 = "SUMMER2021_ACT3_STAGE4_START@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3200307
L22_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "LONELY_NPC_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "L"
L23_1 = "탐정 사무소 설정은 또 어디다 갖다 버리고요?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "探偵事務所の設定はどこにいったんですか！？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "So you quit playing detective?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "偵探事務所人設又換啦？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เธอเลิกเล่นบทนักสืบแล้วงั้นสิ?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Vậy là cô nghỉ chơi trò thám từ rồi à?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "你的那个侦探事务所的设定去哪儿了？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Also hast du die Privatdetektei aufgegeben?"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Alors vous avez arrêté de jouer à la détective ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "SUMMER2021_ACT3_STAGE4_START@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3200307
L23_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "UNIT_HATE"
L23_1.m_Face = L24_1
L24_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "R"
L24_1 = "시끄럽다. 나처럼 위대한 존재를 한 그릇에만 담을 수 있다고 생각하느냐?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "口を慎め。妾のように偉大な存在が一つの設定に縛られていいと思うか？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Silence. I am too great to have just a single identity."
L23_1.m_Talk_ENG = L24_1
L24_1 = "吵什麼吵！像我這麼偉大的存在，一人分飾多角也是很正常的！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "และใช่ ข้า เจ้าแห่งดีม่อนจอมทำลายครอบครัวแห่งรักที่ผิดศีลธรรมผู้นี้มาเพื่อทำให้เจ้าหึงหวงและสร้างเรื่องน้ำเน่าอลหม่าน"
L23_1.m_Talk_THA = L24_1
L24_1 = "Im lặng. Tôi quá vĩ đại để chỉ có một danh tính."
L23_1.m_Talk_VTN = L24_1
L24_1 = "你闭嘴。你觉得像我这样伟大的存在会只做一件事吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Schweig. Ich bin zu großartig, um nur eine einzige Identität zu haben."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Silence. Je suis bien trop grande pour me limiter à une seule identité."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "SUMMER2021_ACT3_STAGE4_START@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3200307
L24_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_LAUGH"
L25_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "R"
L25_1 = "아무튼, 그래. 이 파혼과 치정의 마왕께서 네 질투심을 부추겨 진흙탕 같은 치정극을 연출하기 위해 왕림하셨노라."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "とにかく。そうじゃな、この破婚と痴情の魔王が其方の嫉妬心をそそのかし、泥沼のような痴情劇を演出するために降臨したというわけじゃ。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Anyways, yes. I, the Homewrecker Demon Lord of Illicit Love is here to incite your jealousy and start a chaotic melodrama."
L24_1.m_Talk_ENG = L25_1
L25_1 = "總之，解除婚約和癡情的魔王駕到的目的，是要激發你的嫉妒心，上演灑狗血的癡情劇。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "อย่างไรก็ตาม ข้า เจ้าแห่งดีม่อนจอมทำลายครอบครัวแห่งรักที่ผิดศีลธรรม มาที่นี่เพื่อปลุกระดมความหึงหวงของคุณและเริ่มต้นก่อเรื่องประโลมโลกที่วุ่นวาย"
L24_1.m_Talk_THA = L25_1
L25_1 = "Dù sao thì, đúng vậy. Tôi, Chúa Quỷ Kẻ Phá Hoại Gia Đình và Tình Yêu Bất Chính ở đây để kích động sự ghen tị của cô và bắt đầu một bộ phim hỗn loạn."
L24_1.m_Talk_VTN = L25_1
L25_1 = "总而言之，是的。退婚和婚外情魔王本尊，专为煽动你的嫉妒心，上演狗血的婚外情剧情而来。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Wie auch immer, ja. Ich, die Ehebrecher-Dämonenfürstin der Verbotenen Liebe, bin hier, um deine Eifersucht zu schüren und ein chaotisches Melodrama anzufachen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Quoi qu'il en soit, je suis ici pour attiser la flamme de ta jalousie et déclencher un drame amoureux !"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "SUMMER2021_ACT3_STAGE4_START@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3200307
L25_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_DESPAIR"
L26_1 = "LONELY_NPC_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "L"
L25_1.m_Crash = 15
L26_1 = "저, 전 질투 같은 거 안 했어요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "わ、私は嫉妬などしていませんよ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I-I’m not jealous."
L25_1.m_Talk_ENG = L26_1
L26_1 = "我…我才沒有嫉妒。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ฉะ-ฉันไม่ได้หึงหวงนะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "T-tôi không ghen tị."
L25_1.m_Talk_VTN = L26_1
L26_1 = "我、我不嫉妒。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Ich bin nicht eifersüchtig."
L25_1.m_Talk_DEU = L26_1
L26_1 = "J-Je ne suis pas jalouse..."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "SUMMER2021_ACT3_STAGE4_START@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3200307
L26_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "LONELY_NPC_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "L"
L26_1.m_Crash = 15
L27_1 = "저처럼 예쁘지도 않고 성격도 나쁜 괴짜보단……. 그 여자가 선배님에게 어울릴 테니까……."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "私みたいな美女でもない性格も悪い変わり者より……あの女の方が先輩にふさわしいはずですから……"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I’m not pretty and I’m a twisted geek... Dark is better with that woman..."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我長得又不漂亮，個性也很古怪…那種女生比較適合前輩……"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ฉันไม่สวย แถมยังเป็นเนิร์ดนิสัยประหลาด... ดาร์กเหมาะกับผู้หญิงคนนั้นมากกว่า..."
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi không xinh đẹp và tôi là một kẻ lập dị... Sẽ tốt hơn cho Dark khi ở với người phụ nữ đó..."
L26_1.m_Talk_VTN = L27_1
L27_1 = "因为比起我这种既不漂亮、性格也很差的怪胎……那个女人更适合前辈……"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich bin nicht hübsch und ich bin ein verkorkster Nerd ... Dark ist besser bei dieser Frau aufgehoben ..."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Je ne suis qu'une geek dépressive, et je ne suis même pas jolie... Dark sera plus heureux avec cette femme, c'est sûr."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "SUMMER2021_ACT3_STAGE4_START@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3200307
L27_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "R"
L27_1.m_Crash = 20
L28_1 = "꺄하하하하핫! 걸작이군!"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "キャハハハハッ！　傑作じゃな！"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Kya hah ha! This is something!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "哈哈哈哈！真是可笑！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฮ่าๆๆ! ไม่ธรรมดาเลยนี่!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Kya ha ha! Thú vị đấy!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "嘎哈哈哈哈哈！你可真是有趣！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Kyahaha! Das ist herrlich!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Kya ha ha ! Tu en as, des choses à dire !"
L27_1.m_Talk_FRA = L28_1
