L29_1 = "SUMMER2021_ACT3_STAGE4_START@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3200307
L28_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_SERIOUS"
L29_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "R"
L29_1 = "그래. 네 말대로 너는 그 여자보다 예쁘지도 않고, 성격도 나쁠지 모른다."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "うむ。其方の言うとおり、其方は彼女より綺麗でもない故に、性格も悪いかもしれぬ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "That’s true. You’re not as pretty as her, and you have a bad temper."
L28_1.m_Talk_ENG = L29_1
L29_1 = "你說的沒錯！你長得醜個性又古怪！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ก็จริงนะ เจ้าไม่สวยเท่าหล่อน แถมยังขี้โมโหด้วย"
L28_1.m_Talk_THA = L29_1
L29_1 = "Đúng vậy. Cô không đẹp bằng cô ấy, và tính khí thì nóng nảy."
L28_1.m_Talk_VTN = L29_1
L29_1 = "是的。如你所说，或许你确实没有那个女人漂亮，性格也不好。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Stimmt. Du bist nicht so hübsch wie sie und hast womöglich auch noch eine miese Persönlichkeit."
L28_1.m_Talk_DEU = L29_1
L29_1 = "C'est vrai. Tu n'es pas aussi jolie qu'elle et tu as vraiment un caractère de cochon."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
