L32_1 = "SUMMER2021_ACT3_STAGE4_START@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3200307
L31_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SERIOUS"
L32_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "하지만 승리도 사랑도 결국에는 쟁취하는 것."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "しかし勝利も愛も、結局は勝ち取るもの。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "But love is just like victory. It’s something you fight for."
L31_1.m_Talk_ENG = L32_1
L32_1 = "但是，無論是勝利還是愛情，都是靠爭取而來的！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "แต่ความรักก็เหมือนกับชัยชนะ มันเป็นสิ่งที่เราต้องสู้เพื่อให้ได้มา"
L31_1.m_Talk_THA = L32_1
L32_1 = "Nhưng tình yêu cũng như chiến thắng vậy. Đó là thứ cô phải chiến đấu để giành lấy."
L31_1.m_Talk_VTN = L32_1
L32_1 = "不过胜利和爱情，全都是要争取的。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Aber Liebe ist wie ein Krieg. Dafür kämpft man."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Mais l'amour est une victoire. Il faut se battre pour l'obtenir."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "SUMMER2021_ACT3_STAGE4_START@232#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 232
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3200307
L32_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "이대로 선배를 위해서란 핑계를 대고 얌전히 물러날 생각인 것이냐?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "このまま先輩のためという言い訳をして、何もせず諦めるつもりか？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Are you planning to just run away like that, with an excuse that it’s all for Dark?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "你要騙自己配不上前輩而乖乖退出嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เจ้าคิดจะหนีไปแบบนี้ แล้วก็อ้างว่าทั้งหมดเพื่อดาร์กงั้นเหรอ?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cô định bỏ chạy như thế à, lấy cớ là tất cả vì Dark?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "你想就这样拿为前辈好当借口，安静地退出吗？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Hast du vor, einfach so wegzulaufen, mit der Ausrede, dass alles Dark zuliebe sei?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Alors quoi, après ce château d'excuses que tu t'es construit pour abandonner Dark, tu vas juste t'enfuir la queue entre les pattes ?"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SUMMER2021_ACT3_STAGE4_START@233#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 233
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3200307
L33_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_LAUGH"
L34_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "아니면, 애초부터 너의 <color=#ffd34c>사랑</color>은 고작 그것밖에 안 되었나 보구나."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "いや、そもそも其方の<color=#ffd34c>愛</color>はその程度のものじゃったのか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Is that the <color=#ffd34c>love</color> you have for him?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "還是，打從一開始，你的<color=#ffd34c>愛</color>不過就這樣而已？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "นั่นหรือ<color=#ffd34c>ความรัก</color>ที่เจ้ามีให้เขา?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Đó là <color=#ffd34c>tình yêu</color> mà cô dành cho anh ta à?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "还是说，你的<color=#ffd34c>爱情</color>从一开始就不过如此而已。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ist das die <color=#ffd34c>Liebe</color>, die du für ihn hast?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "C'est tout ce que vaut ce prétendu <color=#ffd34c>amour</color> que tu lui portes ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
