L42_1 = "UNIT_PRIDE"
L41_1.m_Face = L42_1
L42_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "R"
L42_1 = 30
L41_1.m_Crash = L42_1
L42_1 = "그래, 마음은 정했느냐?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "さあ、腹は決めたのか？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "So, you made up your mind?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "怎麼樣？決定好了嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ตัดสินใจได้รึยังล่ะ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Vậy, giờ cô đã hiểu chưa?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "是的，你决定了吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Du hast dich also entschieden?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Alors, tu as pris ta décision ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "SUMMER2021_ACT3_STAGE4_START@242#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 242
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3200307
L42_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "LONELY_NPC_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "L"
L42_1.m_Crash = 15
L43_1 = "맞아. 그 여자가 아무리 잘났다고 해도 상관없어."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "そう。あの女がどれだけ優れていようが構わない。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "You’re right. I don’t care how great that woman is."
L42_1.m_Talk_ENG = L43_1
L43_1 = "沒錯！我才不管那女的有多好！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ถูกของเธอ ฉันไม่สนหรอกว่าผู้หญิงคนนั้นจะดีแค่ไหน"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cô nói đúng. Tôi không quan tâm người phụ nữ đó tuyệt vời ra sao."
L42_1.m_Talk_VTN = L43_1
L43_1 = "没错。不管那个女人有多好都没关系。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Du hast Recht. Es ist mir egal, wie großartig diese Frau ist."
L42_1.m_Talk_DEU = L43_1
L43_1 = "C'est vrai. Cette femme est peut-être belle, ça ne change rien."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "SUMMER2021_ACT3_STAGE4_START@243#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 243
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 3200307
L43_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "LONELY_NPC_NULL_NULL"
L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "L"
L44_1 = "싸워서…… 선배님을 손에 넣겠어."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "戦って……先輩を手に入れてやる。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I will fight her... to win him back."
L43_1.m_Talk_ENG = L44_1
L44_1 = "就算是用蠻力……我也要把前輩搶過來！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฉันจะสู้กับหล่อน... เพื่อชิงเขากลับมา"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi sẽ đánh nhau với cô ta... để giành lại anh ấy."
L43_1.m_Talk_VTN = L44_1
L44_1 = "我要战胜她……得到前辈。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich werde gegen sie kämpfen ... um ihn zurückzugewinnen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je la combattrai... pour reconquérir mon bien aimé."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "SUMMER2021_ACT3_STAGE4_START@244#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 244
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3200307
L44_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L44_1.m_bWaitClick = true
