L44_1.m_Face = "UNIT_LAUGH"
L45_1 = "LONELY_NPC_NULL_NULL"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "L"
L44_1.m_Crash = 50
L45_1 = "사랑은 쟁취하는 자의 것이니까!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "愛は勝ち取るもの！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Love is for those who fight for it!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "愛情本來就是爭來的！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ความรักมีไว้สำหรับผู้ที่ต่อสู้!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tình yêu là dành cho những người chiến đấu vì nó!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "因为爱情属于争取之人！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Liebe ist etwas, das man sich erkämpft!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "L'amour est une île, destinée à ceux qui se battent pour la conquérir !"
L44_1.m_Talk_FRA = L45_1
