L47_1 = "SUMMER2021_ACT3_STAGE4_START@246#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 246
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3200307
L46_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_IDLE"
L47_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L46_1.m_Crash = 20
L47_1 = "오호, 이제야 눈빛이 그럴싸해졌구나."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ほう、やっと目つきがそれっぽくなってきたのう。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Ooh, that’s much better."
L46_1.m_Talk_ENG = L47_1
L47_1 = "呵呵！這個眼神才對嘛！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "อ๊ะ นั่นดีขึ้นเยอะเลยนี่"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ồ, tốt hơn nhiều rồi đấy."
L46_1.m_Talk_VTN = L47_1
L47_1 = "哦吼，现在眼神才变得像那么回事了。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Oh, schon viel besser."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Hé hé, je préfère ça."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "SUMMER2021_ACT3_STAGE4_START@247#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 247
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3200307
L47_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_LAUGH"
L48_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "자, 가라! 가서 예식장의 문을 시원하게 걷어차고 난입하는 거다!"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "さあ、いけ！　結婚式場のドアを蹴飛ばして乱入するのじゃ！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Now, go! Bust into that wedding hall!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "去吧！去一腳踹開婚禮會場的大門，上演搶奪新郎的戲碼！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ไปสิ! พุ่งเข้าไปในห้องจัดงานเลย!"
L47_1.m_Talk_THA = L48_1
L48_1 = "Giờ thì, đi đi! Xong vào sảnh đám cưới đó!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "好了，去吧！去痛快地踹开婚礼礼堂的大门吧！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Jetzt geh! Stürme in diesen Hochzeitssaal!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Cours, Solee ! Va mettre fin à cette union insensée !"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "SUMMER2021_ACT3_STAGE4_START@248#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 248
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3200307
L48_1.m_CutScenStrID = "SUMMER2021_ACT3_STAGE4_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "UNIT_PRIDE"
L48_1.m_Face = L49_1
L49_1 = "ROSARIA_FALLEN_WEDDING_JEALOUSY"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = 40
L48_1.m_Crash = L49_1
L49_1 = "<color=#ffd34c>이 결혼 무효야!</color> 라고 외치면 더욱 좋고!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "<color=#ffd34c>この結婚は無効よ！</color>　と叫ぶのも忘れるな！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "And don’t forget to yell, “<color=#ffd34c>I object to this wedding!</color>“"
L48_1.m_Talk_ENG = L49_1
L49_1 = "最好是再大喊一聲：<color=#ffd34c>我反對！</color>"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แล้วอย่าลืมตะโกนว่า ”<color=#ffd34c>ฉันคัดค้านการแต่งงานครั้งนี้!</color>” ด้วยล่ะ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Và đừng quên hét, “<color=#ffd34c>Tôi phản đối đám cưới này!</color>“"
L48_1.m_Talk_VTN = L49_1
L49_1 = "然后再大声喊出<color=#ffd34c>“我反对这门亲事！”</color>这样的台词就更好了！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Und vergiss nichtm zu schreien: „<color=#ffd34c>Ich bin gegen diese Hochzeit!</color>“"
L48_1.m_Talk_DEU = L49_1
L49_1 = "En en entrant, n'oublie surtout pas de t'écrier : <color=#ffd34c>« Je m'oppose à ce mariage ! »</color>"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
